/* Curated regional overviews. Catalog records remain the source of item and map details. */
(()=>{'use strict';
const descriptions={
 'Isle of the Kings':'Ilha do mosteiro White Raven, ao sul de Ghostlands. Prepare o acesso com Dalbrect, a investigação de Costello e a autorização das catacumbas antes de explorar os subsolos.',
 'Jakundaf Desert':'Deserto do continente principal com a Desert Dungeon, NPCs de enigmas e passagens abertas por chaves diferentes. Escolha a quest e prepare o grupo antes de descer.',
 Kazordoon:'Cidade dos anões construída em vários andares da montanha. Localize os serviços pelo piso e separe a prisão de Dwacatra, as minas externas e as quests dos arredores.',

 Greenshore:'Pequena comunidade ao norte de Thais, com os comerciantes Tokel e Ulrik. Organize os serviços locais e escolha separadamente qualquer caçada nas regiões próximas.',
 Hellgate:'Complexo subterrâneo de Ab’Dendriel, com entrada pela Key 3012, setores de mortos-vivos e conexão de viagem para Draconia. Leia o plano de saída antes do portal.',
 'Ice Islands':'Visão geral das ilhas clássicas Folda, Senja e Vega. Compare balsas, cavernas e as chaves de Alawar’s Vault antes de escolher a ilha e o percurso.',

 Ghostlands:'Região a oeste de Carlin, com cavernas de mortos-vivos, acesso ligado a Isle of the Kings e a quest dos sete selos da Queen of the Banshees. Escolha a profundidade antes de entrar.',
 Ghostland:'Nome usado na documentação do Halloween do Mythera para a referência de Farmer. Esta ficha reúne a loja e o outfit do evento, com links para os guias específicos.',
 'Green Claw Swamp':'Pântano a noroeste de Venore, com a casa de Wyda, caminhos de quests e a Black Knight Villa. Prepare ferramentas, recursos contra veneno e o acesso do objetivo escolhido.',

 'Fields of Glory':'Planícies ao norte e nordeste de Carlin, com referências de NPCs e caminhos para Northport. Prepare a exploração de superfície e escolha separadamente qualquer destino subterrâneo.',
 Folda:'Ilha gelada acessível pela balsa de Nielson. Separe a superfície, as cavernas e a sequência de chaves das Ice Islands antes de explorar os setores profundos.',
 Frostveil:'Local próprio do Mythera associado ao comprador Eirik e citado no evento de Gravepaw. Consulte o comércio documentado e as fontes do evento antes de organizar a visita.',

 Elvenbane:'Castelo em uma ilha a oeste de Ab’Dendriel. O acesso subterrâneo, o pátio e os andares da torre têm perigos diferentes; escolha seu setor antes de atravessar a caverna.',
 "Eremo's Island":'Pequena ilha do sábio Eremo, visitada pelo transporte de Pemaret em Cormaya. Organize a compra do Amulet of Loss ou o aprendizado de magias e confira como retornar.',
 Fibula:'Ilha a sudoeste de Thais, acessível por uma passagem subterrânea. Separe a vila, a Fibula Dungeon e a expedição de Deeper Fibula antes de escolher ferramentas e chaves.',

 Draconia:'Ilha da pirâmide acessível pela travessia de Hellgate e Red Bone Castle. Planeje as chaves da quest, os andares e o mecanismo de retorno antes de partir de Ab’Dendriel.',
 Drefia:'Ruínas a oeste de Darashia, com setores clássicos de mortos-vivos em diferentes profundidades. Escolha uma hunt ou o guia de Medusa Shield antes de entrar.',
 Edron:'Cidade de serviços, transportes e expedições. Separe as cavernas próximas dos setores de Cyclopolis, dos covis de dragões e dos desafios avançados ao norte.',
 Cormaya:'Ilha ligada a Edron, com transporte de Pemaret, ligação com Eremo e acesso ao barco a vapor de Gurbasch. Prepare o destino antes de mudar de cais ou descer ao subsolo.',
 Darashia:'Cidade do norte de Darama. Organize os serviços, as cavernas de Rotworms, a pirâmide dos minotauros e a exploração das ruínas de Drefia.',
 "Ashta'daramai":'Fortaleza dos Blue Djinns nas montanhas de Kha’zeel. Consulte o acesso da facção Marid e os comerciantes antes de levar seu loot para vender.',
 Carlin:'Cidade do noroeste do continente, governada por Queen Eloise. Prepare os suprimentos e escolha entre as cavernas próximas, Ghostlands e as ilhas da região.',
 'Arredores de Venore':'Pântanos, acampamentos e cavernas ao redor de Venore. Escolha o destino e confira o andar antes de sair das passarelas da cidade.',
 'Arredores de Kazordoon':'Colinas, travessias e minas externas de Kazordoon. Separe as rotas de superfície, as partes altas de Femor Hills e os setores profundos das minas.',
 'Ancient Temple':'Complexo de cavernas ao norte de Thais, com setores de caça, salas de quests e caminhos para Mintwallin. Escolha seu destino antes de descer.',
 Ankrahmun:'Cidade de pirâmides no sul de Darama. Prepare os suprimentos, consulte os serviços e escolha uma tumba ou caverna antes de atravessar o deserto.'
};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(name,mythera=false){if(!descriptions[name]||(['Frostveil','Ghostland'].includes(name)&&!mythera))return '';const C=window.CATALOG;
 const link=(type,id,label)=>`<a href="#${type}/${encodeURIComponent(id)}">${esc(label)} <span aria-hidden="true">↗</span></a>`;
 const npc=(name,label)=>{const n=C.npcs.find(n=>n.name===name);return n?`<a class="ab-service" href="#npc/${encodeURIComponent(name)}">${n.image?`<img src="${esc(n.image)}" width="48" height="48" alt="" loading="lazy">`:''}<span><strong>${esc(label)}</strong><small>${esc(name)} · ficha e mapa ↗</small></span></a>`:'';};
 const section=(title,body)=>`<section><h4>${title}</h4>${body}</section>`;
 const box=(label,title,text,links)=>`<article><span class="ab-step">${label}</span><h5>${title}</h5><p>${text}</p><div class="city-guide-links">${links}</div></article>`;
 const hunt=id=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return h?`<a class="city-guide-row" href="#hunt/${esc(h.id)}"><strong>${esc(h.name)}</strong><span>${h.level}+ de referência · abrir hunt ↗</span></a>`:'';};
 const creatures=names=>`<div class="city-guide-creatures">${names.map(name=>{const c=window.DATA.creatures.find(c=>c.name.toLowerCase()===name.toLowerCase());return c?`<a href="#creature/${encodeURIComponent(c.name)}">${window.DATA.monsters[c.name.toLowerCase()]?`<img src="${esc(window.DATA.monsters[c.name.toLowerCase()])}" width="44" height="44" alt="" loading="lazy">`:''}<span>${esc(c.name)}</span></a>`:'';}).join('')}</div>`;
 const key=(n,label)=>`<a href="/chaves/key-${n}/" target="_blank" rel="noopener">${esc(label)} ↗</a>`;
 const scope=mythera&&!['Frostveil','Ghostland'].includes(name)?'<aside class="city-guide-notice"><strong>Você está no Mythera</strong><p>O roteiro geográfico abaixo usa a base 7.4. Posições e caminhos clássicos ainda precisam de conferência em campo neste servidor. Regras exclusivas confirmadas aparecem identificadas como Mythera.</p></aside>':'';
 let body='';
 if(name==='Isle of the Kings'){
 body=section('Acesso à ilha e autorização das catacumbas',`<div class="ab-access-grid">${box('01 · GHOSTLANDS','Entregue o Family Brooch a Dalbrect','O guia de The White Raven Monastery registra a coleta do Family Brooch em Ghostlands e sua entrega a Dalbrect para liberar a passagem. Apenas iniciar a conversa não conclui essa etapa de acesso.',link('quest','the-white-raven-monastery','Guia do acesso à ilha')+npc('Dalbrect','Referência do embarque em Ghostlands'))}${box('02 · MOSTEIRO','Fale com Costello sobre a investigação','Na ilha, a autorização das portas das catacumbas está ligada à conversa com Costello sobre Fugio e à aceitação da investigação. A viagem com Dalbrect e a permissão para explorar o subsolo são etapas diferentes.',npc('Costello','Investigação e acesso das catacumbas'))}${box('03 · EXPLORAÇÃO','Escolha o andar antes de entrar','A hunt de Skeletons aponta uma referência no primeiro subsolo. Os pisos profundos e as conexões de quests exigem outro preparo; não use o nível sugerido dessa hunt para explorar todas as descidas.',hunt('carlin-isle-kings-skeletons'))}</div>`)
 +section('White Raven Monastery: acompanhe as etapas',`<ol class="city-guide-checklist"><li><strong>Continente:</strong> consulte o roteiro de Ghostlands e obtenha o Family Brooch.</li><li><strong>Viagem:</strong> conclua a entrega a Dalbrect e confirme a passagem para a ilha.</li><li><strong>Costello:</strong> leia a conversa da investigação antes de atravessar portas do mosteiro.</li><li><strong>Diário:</strong> confira o objetivo do Monk’s Diary no roteiro completo e sua entrega a Costello.</li><li><strong>Retorno:</strong> organize a volta antes de explorar áreas restritas ou gastar suas reservas.</li></ol><div class="city-guide-links">${link('quest','the-white-raven-monastery','Abrir todas as etapas')}${link('explorador/cities','Ghostlands','Preparar a coleta em Ghostlands')}</div>`)
 +section('Key 3350: o andar restrito tem consequências',`<div class="ab-access-grid">${box('OBTENÇÃO','Estante próxima de Costello','A ficha da chave registra uma estante junto de documentos do monastério. Use o guia ilustrado para conferir o recipiente e a porta correta; a chave não é o item que libera a viagem com Dalbrect.',key('3350','Key 3350 · obtenção e uso'))}${box('ÁREA RESTRITA','Leia as condições antes de entrar','A Key 3350 está ligada aos andares superiores restritos. Entrar nessa área pode gerar cobrança para sair da ilha. A permissão das catacumbas não deve ser interpretada como autorização para todas as portas do mosteiro.',key('3350','Conferir as observações da chave'))}</div>`)
 +section('Hunt documentada e perigos dos subsolos',`${hunt('carlin-isle-kings-skeletons')}<p>A ficha de Skeletons usa nível 15 como referência para o primeiro subsolo. Confira autorização, ferramentas e caminho de volta mesmo para essa caçada. Uma porta aberta por outro jogador não comprova que seu personagem concluiu a investigação necessária.</p>`+creatures(['Skeleton','Ghoul','Demon Skeleton','Monk','Ghost','Stalker','Giant Spider'])+'<p>Os nomes acima abrangem diferentes andares e caminhos da ilha. Inimigos invisíveis e criaturas fortes nos setores profundos exigem recursos próprios; eles não formam um único respawn ao lado do desembarque.</p>')
 +section('NPCs: superfície e profundezas',`<div class="ab-service-grid">${npc('Costello','Mosteiro e investigação')}${npc('Captain Jack','Retorno ao continente')}${npc('A Lost Soul','Referência no subsolo')}${npc('A Tainted Soul','Referência no subsolo')}${npc('A Tortured Soul','Referência no subsolo')}</div><p>Costello e Captain Jack têm posições de superfície registradas no catálogo. As três almas têm referências no andar 12. Captain Jack oferece o retorno ao continente, mas pode recusar a passagem após a entrada na área restrita do mosteiro; confira a advertência da Key 3350 antes de subir. Consulte a ficha e o objetivo do roteiro antes de procurar um NPC profundo; a lista não representa lojas de suprimentos.</p>`)
 +section('Conexão com a Queen of the Banshees',`<div class="ab-access-grid">${box('QUEST SEPARADA','Sete selos, outros requisitos','A quest The Queen of the Banshees envolve Ghostlands e referências ligadas à ilha. O catálogo registra nível 60 e preparação própria. Visitar o mosteiro ou concluir o acesso de Dalbrect não significa completar os sete selos.',link('quest','the-queen-of-the-banshees','Guia da Queen of the Banshees'))}${box('PREPARAÇÃO','Escolha a expedição completa','Se o objetivo for a Banshee, confira enigmas, combates, ferramentas e equipe no guia específico. Se for somente a hunt de Skeletons, siga sua própria referência sem transformar a volta em uma exploração improvisada dos pisos profundos.',link('explorador/cities','Ghostlands','Ghostlands · setores e quests'))}</div>`)
 +section('Checklist antes do embarque','<ul class="city-guide-checklist"><li><strong>Acesso:</strong> confira a entrega do Family Brooch a Dalbrect.</li><li><strong>Autorização:</strong> siga a investigação de Costello para as catacumbas.</li><li><strong>Ferramentas:</strong> consulte Rope, Shovel, Pick e luz conforme a expedição.</li><li><strong>Área restrita:</strong> leia as consequências da Key 3350 antes de subir.</li><li><strong>Retorno:</strong> preserve cura e recursos para sair da ilha e voltar ao continente.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Posso embarcar só conversando com Dalbrect?</summary><p>O roteiro clássico exige concluir a etapa da entrega do Family Brooch. Iniciar o diálogo não equivale a liberar a passagem.</p></details><details><summary>A Key 3350 abre as catacumbas?</summary><p>Seu uso registrado é na área restrita dos andares superiores. A autorização das catacumbas envolve Costello e a investigação sobre Fugio.</p></details><details><summary>Todas as quests da wiki atual pertencem ao 7.4?</summary><p>Este resumo usa os guias clássicos revisados. Quests e bosses de versões posteriores não foram adicionados como conteúdo clássico da ilha.</p></details>');
 }else if(name==='Jakundaf Desert'){
 body=section('Deserto, dungeon e objetivos diferentes',`<div class="ab-access-grid">${box('01 · DESTINO','Escolha a quest antes de descer','Jakundaf é uma região do continente principal, diferente do deserto de Darama. O atlas mostra a superfície; as quests e as chaves possuem referências próprias no subsolo. Não use esse marcador para procurar uma tumba de Ankrahmun.',link('quest','the-desert-dungeon','Guia de The Desert Dungeon'))}${box('02 · GRUPO','A quest clássica usa quatro vocações','Reúna Knight, Paladin, Druid e Sorcerer, todos no nível 20 ou acima. Confira os itens e as posições no roteiro antes de iniciar o percurso; o grupo precisa estar preparado para concluir a etapa em conjunto.',link('quest','the-desert-dungeon','Preparar o grupo e o mecanismo'))}${box('03 · EXPLORAÇÃO','Biblioteca, teleports e Panpipe','São objetivos separados dentro do sistema de cavernas. Cada chave abre uma passagem específica. Escolha o destino antes de entregar itens a NPCs ou atravessar uma porta desconhecida.',link('quest','panpipe','Guia de Panpipe')+key('4009','Key 4009 · biblioteca'))}</div>`)
 +section('The Desert Dungeon: itens de cada vocação',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Preparação clássica · quatro personagens de nível 20+</caption><thead><tr><th scope="col">Vocação</th><th scope="col">Item a separar</th></tr></thead><tbody><tr><th scope="row">Knight</th><td>Sword</td></tr><tr><th scope="row">Paladin</th><td>Crossbow</td></tr><tr><th scope="row">Druid</th><td>Apple / Red Apple</td></tr><tr><th scope="row">Sorcerer</th><td>Spellbook</td></tr></tbody></table></div><p>Os itens são usados no mecanismo da quest. Se o Paladin depende de uma Crossbow para combater, leve outra para a etapa, preservando a arma da viagem. Confira também Shovel para a entrada e coordene as posições antes de acionar a alavanca.</p><p>A wiki atual inclui a vocação Monk e alterações posteriores. O roteiro desta página mantém a composição clássica de quatro personagens; não adiciona um quinto participante como requisito do 7.4.</p><div class="city-guide-links">${link('quest','the-desert-dungeon','Ver posições, percurso e recompensas')}</div>`)
 +section('Chaves: biblioteca e salas de enigmas',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Jakundaf · obtenções e portas distintas</caption><thead><tr><th scope="col">Chave</th><th scope="col">Como obter · resumo</th><th scope="col">O que abre</th></tr></thead><tbody><tr><th scope="row">${key('4022','Key 4022')}</th><td>Troca de 1 Roll com Hagor.</td><td>Sala onde é coletada a Key 4009.</td></tr><tr><th scope="row">${key('4009','Key 4009')}</th><td>Baú da sala aberta com 4022.</td><td>Biblioteca subterrânea.</td></tr><tr><th scope="row">${key('4023','Key 4023')}</th><td>Teste de Adrenius; 500 gp e respostas de Netlios.</td><td>Sala dos quatro teleports.</td></tr><tr><th scope="row">${key('4037','Key 4037')}</th><td>Itens e respostas no diálogo de Nemal.</td><td>Hall of Lost Doors.</td></tr></tbody></table></div><p>A Key 4009 abre a biblioteca; ela não abre o quarto onde a própria chave é coletada. Para Nemal e Adrenius, abra o guia completo antes de iniciar a conversa: a lista de materiais e a ordem das respostas fazem parte da preparação.</p>`)
 +section('Fire Devils e Panpipe: confira a passagem certa',`<div class="ab-access-grid">${box('KEY 4001','Porta do fosso dos Fire Devils','A obtenção registrada envolve um baú protegido por Orc Berserkers e uma passagem com Pick. Confira as imagens e os perigos antes de escolher esse objetivo; ele não é uma etapa obrigatória da quest das quatro vocações.',key('4001','Key 4001 · obtenção e uso'))}${box('KEY 4055','Porta da Panpipe Quest','A ficha registra a coleta usando uma pedra ao sul da entrada da dungeon. Consulte o guia da chave e o roteiro da Panpipe para conferir a porta, os encontros e os recipientes de recompensa.',key('4055','Key 4055 · referência de coleta')+link('quest','panpipe','Panpipe · guia completo'))}</div>`)
 +section('NPCs em andares diferentes',`<div class="ab-service-grid">${npc('Adrenius','Teste e Key 4023')}${npc('Hagor','Troca ligada à Key 4022')}${npc('Nemal','Itens e Key 4037')}</div><p>Adrenius tem referência no andar 8, enquanto Hagor e Nemal estão no andar 10. As fichas mostram posições e diálogos registrados, sem afirmar que todos ficam perto da mesma entrada.</p>`)
 +section('Criaturas: o caminho errado muda o risco',creatures(['Orc Berserker','Fire Devil','Beholder','Scorpion'])+'<p>Os encontros variam por ramo da dungeon. A quest das quatro vocações e os objetivos das chaves têm trajetos próprios; uma indicação de nível 20 para a quest não autoriza explorar todo o complexo. Prepare cura e recursos contra veneno conforme o caminho.</p>')
 +section('Checklist antes da descida','<ul class="city-guide-checklist"><li><strong>Grupo:</strong> para The Desert Dungeon, confira as quatro vocações e nível 20 em cada personagem.</li><li><strong>Itens:</strong> separe Sword, Crossbow, Apple e Spellbook sem comprometer o equipamento da viagem.</li><li><strong>Ferramentas:</strong> confira Shovel, Rope, Pick e luz conforme a passagem escolhida.</li><li><strong>NPCs:</strong> prepare Roll e os demais materiais exigidos antes de iniciar as trocas de chaves.</li><li><strong>Destino e volta:</strong> abra o roteiro completo e registre mudanças de andar antes de atravessar teleports.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Jakundaf é o deserto de Ankrahmun?</summary><p>Não. Esta ficha trata do deserto do continente principal e de sua dungeon. As tumbas de Darama e Ankrahmun têm páginas e acessos próprios.</p></details><details><summary>Preciso das seis chaves para fazer a quest em grupo?</summary><p>As chaves listadas pertencem a objetivos e passagens distintos. Siga os requisitos do roteiro escolhido; não há uma exigência geral de coletar todas para cada visita.</p></details><details><summary>O grupo clássico precisa de Monk?</summary><p>O roteiro 7.4 usa Knight, Paladin, Druid e Sorcerer. A inclusão de Monk na wiki atual pertence a alterações posteriores.</p></details>');
 }else if(name==='Kazordoon'){
 body=section('Encontre o serviço pelo andar',`<div class="ab-service-grid">${npc('Uzgod','Armas e comércio de loot')}${npc('Kroox','Armaduras, escudos e equipamentos')}${npc('Maryza','Alimentos do catálogo')}${npc('Bezil','Mochilas e utensílios')}${npc('Nezil','Mochilas e utensílios')}${npc('Lokur','Cartas e parcels')}</div><p>Kazordoon tem muitos serviços abaixo e acima da superfície. Confira o andar na ficha do NPC antes de seguir pelo mapa: um ponto no mesmo X/Y pode estar separado por vários pisos. As ofertas distinguem o que o NPC compra de você e o que ele vende ao jogador.</p>`)
 +section('Organize as compras antes de sair',`<div class="ab-access-grid">${box('COMBATE','Arma, defesa e capacidade','Uzgod e Kroox têm listas próprias de ofertas. Compare item, preço e peso antes de comprar ou carregar loot. Uma oferta de venda não informa o valor que o NPC pagaria pelo seu equipamento.',link('npc','Uzgod','Consultar armas em Uzgod')+link('npc','Kroox','Consultar equipamentos em Kroox'))}${box('SUPRIMENTOS','Comida e recipientes','Maryza reúne alimentos; Bezil e Nezil possuem mochilas e utensílios registrados. Confira a ficha antes de contar com uma ferramenta específica para a expedição.',link('npc','Maryza','Comidas de Maryza')+link('npc','Bezil','Ofertas de Bezil')+link('npc','Nezil','Ofertas de Nezil'))}${box('OUTROS SERVIÇOS','Bebidas, joias e decoração','Jimbin, Tezila e Iwar têm funções distintas. Separe a compra necessária para uma quest da simples venda ou aquisição de itens, observando o sentido da oferta.',npc('Jimbin','Bebidas')+npc('Tezila','Joias e itens registrados')+npc('Iwar','Móveis e decoração'))}</div>`)
 +section('Professores e referências da cidade',`<div class="ab-service-grid">${npc('Duria','Magias registradas no catálogo')}${npc('Etzel','Magias registradas no catálogo')}${npc('Emperor Kruzak','Aposentos do imperador')}${npc('Kawill','Referência nas profundezas')}${npc('Pydar','Referência nas profundezas')}</div><p>Confira os requisitos de vocação, promoção e preço na ficha da magia ou no serviço documentado. A existência de um NPC na cidade não significa que todas as ofertas atuais da wiki estejam disponíveis no 7.4.</p>`)
 +section('Emperor’s Cookies e as chaves da cidade',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Chaves do percurso clássico · funções diferentes</caption><thead><tr><th scope="col">Chave</th><th scope="col">Obtenção e destino</th></tr></thead><tbody><tr><th scope="row">${key('3800','Key 3800')}</th><td>Baú no fim da passagem secreta dos aposentos; abre a sala ao norte do trono.</td></tr><tr><th scope="row">${key('3801','Key 3801')}</th><td>Recipiente da sala aberta com 3800, junto dos cookies; permite seguir ao setor do arsenal.</td></tr><tr><th scope="row">${key('3802','Key 3802')}</th><td>Baú do setor dos quartéis, alcançado com 3801; abre Dwacatra.</td></tr></tbody></table></div><div class="city-guide-links">${link('quest','emperor-s-cookies','Emperor’s Cookies · roteiro completo')}</div><p>Leia o caminho antes de explorar os aposentos ou abrir portas aleatórias. A numeração ajuda a reconhecer as chaves, mas o guia de cada uma identifica a coleta e a passagem correspondente.</p>`)
 +section('Dwacatra fica na cidade subterrânea',`<div class="ab-access-grid">${box('PRISÃO · ACESSO PRÓPRIO','Confira a Key 3802 antes de ir','A hunt aponta uma referência no piso principal da prisão, subsolo −7. Consulte a preparação e o acesso antes de sair; o marcador de respawn não é a porta de entrada da prisão.',key('3802','Key 3802 · acesso de Dwacatra')+hunt('kazordoon-dwacatra'))}${box('OUTRO CONJUNTO DE HUNTS','As minas externas ficam a oeste','Dwarfs, Soldiers, Guards e Geomancers possuem setores próprios nas minas externas. Use o resumo dos arredores para comparar essas opções; a prisão não é uma continuação equivalente das primeiras minas.',link('explorador/cities','Arredores de Kazordoon','Minas externas e Femor Hills')+hunt('dwarf-mines')+hunt('dwarf-guards'))}</div>`)
 +section('Quests: escolha o percurso antes da recompensa',`<div class="ab-access-grid">${box('MINAS DOS DWARFS','Circle Room e Crusader Helmet','São guias diferentes, com requisitos e profundidades próprios. O catálogo registra referências de nível 32 e 35, respectivamente; confira os combates e a preparação antes de iniciar o caminho.',link('quest','circle-room','Guia de Circle Room')+link('quest','crusader-helmet','Guia de Crusader Helmet'))}${box('CAVERNAS E TORRES','Iron Hammer e Steel Helmet','Abra o roteiro da recompensa pretendida para conferir entrada e ferramentas. Uma referência de nível zero não significa que o caminho entre salas seja seguro para qualquer personagem.',link('quest','iron-hammer','Guia de Iron Hammer')+link('quest','steel-helmet','Guia de Steel Helmet'))}${box('PARADOX TOWER','Expedição nos arredores','A Key 3899 e o guia de The Paradox Tower pertencem a um destino com enigmas e deslocamentos próprios. Confira todos os requisitos antes de deixar a cidade.',key('3899','Key 3899 · obtenção')+link('quest','the-paradox-tower','Guia de The Paradox Tower'))}</div>`)
 +section('Transportes: subsolo e colinas são embarques distintos',`<div class="ab-service-grid">${npc('Brodrosch','Steamship no subsolo')}${npc('Uzon','Referência de tapete em Femor Hills')}</div><div class="city-guide-links">${link('explorador/cities','Cormaya','Cormaya · ligação do steamship')}${link('explorador/cities','Arredores de Kazordoon','Femor Hills · referência das colinas')}</div><p>Brodrosch tem referência no andar 15, enquanto Uzon está nas colinas elevadas de Femor Hills. Confira o destino e o acesso do NPC antes de viajar. Farmine, sistema moderno de vagões e outros serviços posteriores não foram incluídos como transporte clássico.</p>`)
 +section('Criaturas: minas, prisão e arredores',creatures(['Dwarf','Dwarf Soldier','Dwarf Guard','Dwarf Geomancer','Rotworm','Minotaur','Dragon'])+'<p>Os nomes abrangem caçadas e caminhos distintos. Escolha a hunt e confira seu nível, andar e perigos antes de sair; a dificuldade de um Dwarf não descreve as salas profundas de Geomancers ou a prisão de Dwacatra.</p>')
 +section('Checklist antes da expedição','<ul class="city-guide-checklist"><li><strong>Andar:</strong> confira o piso de cada loja, passagem e embarque.</li><li><strong>Destino:</strong> distinga cidade, Dwacatra, minas externas e Femor Hills.</li><li><strong>Chaves:</strong> prepare 3800–3802 ou 3899 conforme o guia escolhido.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e luz; acrescente os itens próprios da quest.</li><li><strong>Reservas:</strong> preserve cura, comida, mana e capacidade para o percurso de volta.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>O mapa da cidade aponta a entrada das minas externas?</summary><p>Ele abre uma referência urbana de Kazordoon no andar 9. As minas externas, a prisão e as hunts têm mapas próprios.</p></details><details><summary>Dwacatra e as minas são a mesma área?</summary><p>Não. Dwacatra é a prisão subterrânea com acesso pela Key 3802. As minas externas ficam a oeste e possuem seus próprios setores de caça.</p></details><details><summary>Por que um NPC não aparece no piso em que estou?</summary><p>A cidade é vertical. Confira o andar da ficha e procure as transições adequadas; proximidade no mapa horizontal não significa acesso pelo mesmo piso.</p></details><details><summary>Todos os serviços da Kazordoon atual estão incluídos?</summary><p>Este resumo usa os NPCs e guias da base clássica revisada. Serviços e regiões posteriores não foram apresentados como conteúdo do 7.4.</p></details>');
 }else if(name==='Greenshore'){
 body=section('Visite a vila com um objetivo definido',`<div class="ab-access-grid">${box('01 · REGIÃO DE THAIS','Comunidade ao norte da cidade','Use Thais como base para preparar a caminhada até Greenshore. O atlas abre uma visão geral da vila; ele não calcula uma rota desde o depot nem identifica todas as passagens das regiões próximas.',link('explorador/cities','Thais','Preparar a viagem em Thais'))}${box('02 · COMÉRCIO LOCAL','Confira a loja antes de viajar','Tokel e Ulrik têm ofertas registradas na base comunitária 7.4. Escolha comida ou equipamento e confira os produtos na ficha do comerciante. A presença de uma loja não garante todos os suprimentos de uma expedição.',npc('Tokel','Alimentos do catálogo')+npc('Ulrik','Armas e equipamentos'))}${box('03 · CONTINUAÇÃO','Escolha uma hunt pelo guia próprio','O catálogo não possui uma hunt exclusiva de Greenshore nem uma quest clássica própria associada à vila. Para caçar, abra uma ficha da região de Thais e confira o acesso, sem usar o centro de Greenshore como entrada de uma dungeon.',link('explorador/cities','Thais','Escolher hunts e quests de Thais'))}</div>`)
 +section('Tokel: alimentos e planejamento da carga',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Tokel vende ao jogador · preços da referência clássica</caption><thead><tr><th scope="col">Alimento</th><th scope="col">Preço</th></tr></thead><tbody>${C.npcs.find(n=>n.name==='Tokel').sell.map(o=>{const item=C.items.find(i=>String(i.id)===String(o.item));return `<tr><th scope="row">${esc(item?.name||o.item)}</th><td>${o.price} gp</td></tr>`;}).join('')}</tbody></table></div><p>Confira quantidade, preço e capacidade antes de confirmar a compra. Escolha os alimentos para a duração pretendida da viagem e preserve espaço para cura, ferramentas e loot. O preço unitário não informa o tempo de alimentação de cada comida.</p><div class="city-guide-links">${link('npc','Tokel','Abrir ficha de Tokel')}${link('explorador','food','Consultar alimentos e duração')}</div>`)
 +section('Ulrik: compare o equipamento antes de comprar',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Ulrik vende ao jogador · base comunitária 7.4</caption><thead><tr><th scope="col">Equipamento</th><th scope="col">Preço</th></tr></thead><tbody>${C.npcs.find(n=>n.name==='Ulrik').sell.map(o=>{const item=C.items.find(i=>String(i.id)===String(o.item));return `<tr><th scope="row">${esc(item?.name||o.item)}</th><td>${o.price} gp</td></tr>`;}).join('')}</tbody></table></div><p>As ofertas acima são de venda do NPC para você. Não representam o valor que ele pagaria pelo mesmo item. Consulte atributos, peso e tipo de arma na biblioteca antes de trocar uma peça; comprar uma arma de outra skill pode prejudicar seu preparo.</p><div class="city-guide-links">${link('npc','Ulrik','Abrir ficha de Ulrik')}${link('catalog','itens','Comparar itens no catálogo')}</div>`)
 +section('Hunts próximas: cada destino tem seu acesso',`<div class="ab-access-grid">${box('THAIS · CAVERNAS','Trolls e Ancient Temple','São alternativas do catálogo de Thais, com caminhos próprios. O mapa da hunt de Trolls ou de Rotworms não é o mapa da vila. Escolha o setor antes de sair e confira as ferramentas indicadas na ficha.',hunt('troll-thais')+hunt('thais-temple-rotworms'))}${box('MOUNT STERNUM','Cyclops exigem outro preparo','Mount Sternum tem ficha regional e hunt próprias. Consulte o nível sugerido e os perigos dos Cyclops antes de incluir essa caçada na viagem. O circuito não começa automaticamente no marcador de Greenshore.',link('explorador/cities','Mount Sternum','Explorar Mount Sternum')+hunt('cyclops-sternum'))}</div>`)
 +section('Reconheça os perigos da exploração',creatures(['Wolf','Poison Spider','Rotworm','Orc','Cyclops'])+'<p>Estas fichas ajudam a preparar o deslocamento e as caçadas próximas citadas acima. Não descrevem um único respawn da vila. Ver uma criatura fraca na superfície não identifica a dificuldade de uma caverna ou passagem de montanha.</p>')
 +section('Checklist antes da caminhada','<ul class="city-guide-checklist"><li><strong>Objetivo:</strong> escolha compra de alimentos, equipamento ou uma expedição com guia próprio.</li><li><strong>Oferta:</strong> confira se o NPC vende o item desejado e leia a proposta antes de aceitar.</li><li><strong>Capacidade:</strong> preserve espaço para ferramentas e reservas depois de comprar comida ou equipamentos.</li><li><strong>Ferramentas:</strong> se vai continuar para cavernas, confira Rope, Shovel e luz no roteiro escolhido.</li><li><strong>Retorno:</strong> mantenha Thais como referência para reabastecer e não use uma passagem desconhecida como atalho.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Greenshore substitui os serviços de Thais?</summary><p>O resumo documenta as ofertas de Tokel e Ulrik. Ele não confirma uma estrutura completa de cidade, como todos os professores, lojas ou serviços que seu personagem possa precisar.</p></details><details><summary>A vila tem uma hunt própria no catálogo?</summary><p>A base revisada ainda não possui uma ficha de hunt exclusiva de Greenshore. Os links apresentados levam a destinos de Thais com suas próprias localizações e requisitos.</p></details><details><summary>As quests e cavernas da wiki atual foram adicionadas?</summary><p>Este guia utiliza os comerciantes e registros clássicos já revisados. Áreas e missões de versões posteriores não foram incorporadas como conteúdo confirmado do 7.4.</p></details>');
 }else if(name==='Hellgate'){
 body=section('A chave vem antes do portal',`<div class="ab-access-grid">${box('01 · AB’DENDRIEL','Prepare a viagem na cidade','Separe cura, mana, comida e ferramentas para uma travessia longa. A Key 3012 dá acesso às portas de Hellgate; a compra não obriga você a atravessar o portal. Confira o objetivo e o retorno antes de seguir.',link('explorador/cities',"Ab'Dendriel",'Serviços de Ab’Dendriel'))}${box('02 · KEY 3012','Elathriel vende por 5.000 gp','O guia ilustrado acompanha a descida até o nível das portas e o desvio para Elathriel. O NPC tem referência no andar 9; as portas ficam no andar 10. Confirme o preço no diálogo e confira a chave recebida.',key('3012','Key 3012 · compra ilustrada')+link('npc','Elathriel','Localizar Elathriel'))}${box('03 · DECISÃO DE ENTRADA','Planeje como sair antes de atravessar','Depois do portal, não conte com voltar pelo mesmo teleporte. Escolha uma hunt ou uma travessia definida e consulte o percurso completo antes de entrar. Ter a chave não garante recursos para alcançar a saída.',key('3012','Rever o acesso e a entrada'))}</div>`)
 +section('Como comprar sem iniciar a expedição',`<ol class="city-guide-checklist"><li><strong>Dinheiro:</strong> leve os 5.000 gp registrados no guia e espaço para receber a chave.</li><li><strong>Entrada subterrânea:</strong> consulte as imagens da Key 3012 para seguir as descidas de Ab’Dendriel.</li><li><strong>Desvio para o NPC:</strong> no nível das portas, siga o caminho indicado até Elathriel, um andar acima.</li><li><strong>Diálogo:</strong> use <code>hi</code>, depois <code>key</code>; confira a oferta e responda <code>yes</code> quando ela corresponder à compra desejada.</li><li><strong>Preparação:</strong> após receber a chave, você pode voltar à cidade para organizar a expedição antes de usar o portal.</li></ol>`)
 +section('Hunts por profundidade',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Hellgate clássica · níveis sugeridos para cada setor</caption><thead><tr><th scope="col">Hunt</th><th scope="col">Nível de referência</th><th scope="col">Profundidade</th></tr></thead><tbody>${[['abdendriel-hellgate-ghouls','Subsolo −4'],['abdendriel-hellgate-demon-skeletons','Subsolo −4 · setor próprio'],['abdendriel-hellgate-beholders','Subsolo −7']].map(([id,area])=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${h.level}+</td><td>${area}</td></tr>`;}).join('')}</tbody></table></div><p>A posição de respawn não indica uma entrada desde a cidade nem uma ligação direta entre os setores. Mesmo hunts no mesmo andar podem exigir deslocamentos diferentes. O nível sugerido depende de equipamento, skills, vocação e recursos de cura.</p>`)
 +section('Biblioteca e A Wrinkled Beholder',`<div class="ab-access-grid">${box('NPC DAS PROFUNDEZAS','A Wrinkled Beholder','O NPC tem referência no andar 13, abaixo de Ab’Dendriel. Sua ficha apresenta localização e diálogos; não é um comerciante de suprimentos para reabastecer a hunt. Confira o caminho antes de incluir a visita na expedição.',npc('A Wrinkled Beholder','Biblioteca de Hellgate'))}${box('LINGUAGEM 469','Separe mistério de solução documentada','A biblioteca é associada à linguagem numérica 469. A existência de livros e mistérios não constitui um roteiro confirmado para obter tesouros. Este resumo não apresenta teorias sobre a biblioteca como etapas de uma quest resolvida.',link('npc','A Wrinkled Beholder','Consultar a referência do NPC'))}</div>`)
 +section('Draconia: outra etapa de uma viagem longa',`<div class="ab-access-grid">${box('TRAVESSIA','Hellgate e Red Bone Castle','O acesso clássico de Draconia passa por Hellgate e Red Bone Castle. A página de Draconia reúne a sequência da pirâmide e as hunts da ilha. Chegar a Hellgate não significa que você já chegou ao início das salas de recompensa.',link('explorador/cities','Draconia','Preparar a travessia para Draconia'))}${box('CHAVES DIFERENTES','3012 não substitui 3001–3008','As chaves da pirâmide têm obtenção e funções próprias. Consulte os mecanismos, a preparação da equipe e a saída no guia de Draconia, especialmente se pretende fazer a quest em vez de uma caçada curta.',link('quest','draconia','Guia da quest de Draconia')+key('3001','Início da sequência da pirâmide')+key('3008','Etapa final e mecanismo de saída'))}</div>`)
 +section('Criaturas: organize o combate por setor',creatures(['Ghoul','Demon Skeleton','Beholder','Skeleton','Giant Spider'])+'<p>Os encontros dependem do setor e do caminho escolhido. As fichas ajudam a conferir ataques e resistência antes de escolher munição ou runas. Preserve recursos para atravessar corredores e mudanças de andar no retorno, além do consumo da própria hunt.</p>')
 +section('Checklist antes do portal','<ul class="city-guide-checklist"><li><strong>Chave:</strong> confira a Key 3012 e não dependa de encontrar portas abertas.</li><li><strong>Destino:</strong> escolha Ghouls, Demon Skeletons, Beholders, biblioteca ou a travessia para Draconia.</li><li><strong>Ferramentas:</strong> confira Rope, luz e os requisitos adicionais do roteiro.</li><li><strong>Reservas:</strong> prepare recursos para a viagem inteira; o NPC da biblioteca não substitui as lojas da cidade.</li><li><strong>Saída:</strong> leia o percurso antes de atravessar o teleporte e registre as mudanças de andar.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Comprar a Key 3012 me leva a Hellgate?</summary><p>Não. A compra é feita com Elathriel. O guia distingue o acesso ao NPC das portas e do portal; você pode preparar a chave antes de iniciar a travessia.</p></details><details><summary>Posso voltar pelo portal assim que entrar?</summary><p>O roteiro clássico alerta para não contar com o retorno pelo mesmo teleporte. Planeje o caminho de saída antes de atravessá-lo.</p></details><details><summary>O atlas mostra a posição exata da entrada?</summary><p>O mapa geral usa uma referência subterrânea de Hellgate. A Key 3012 tem imagens próprias da descida, do acesso ao NPC e das portas.</p></details><details><summary>Preciso completar Draconia para toda hunt de Hellgate?</summary><p>São objetivos diferentes. A página aponta a conexão com Draconia, mas a preparação e o percurso de uma hunt devem ser conferidos na sua própria ficha.</p></details>');
 }else if(name==='Ice Islands'){
 body=section('Três ilhas clássicas, objetivos diferentes',`<div class="ab-access-grid">${box('FOLDA','Superfície e cavernas profundas','Folda reúne referências de Frost Trolls, Rotworms e Minotaurs. Também participa da rota longa de Alawar’s Vault e da sequência das chaves 4501–4503. Escolha a profundidade antes de desembarcar.',link('explorador/cities','Folda','Guia detalhado de Folda'))}${box('SENJA','Vila, Frost Trolls e castelo','A ilha tem NPCs da vila e uma referência de Frost Trolls em uma pequena caverna ao norte. O castelo participa do acesso direto de Alawar’s Vault; esse objetivo tem preparação própria.',link('explorador/cities','Senja','Consultar Senja')+hunt('carlin-senja-frost-trolls'))}${box('VEGA','Outra ilha, outra caverna','Vega tem uma referência de Rotworms no catálogo e Carlson como NPC de transporte. Abra a hunt e confira a entrada e o retorno da ilha em vez de seguir o mapa de uma caverna de Folda.',link('explorador/cities','Vega','Consultar Vega')+hunt('carlin-vega-rotworms'))}</div>`)
 +section('Balsas: comece no continente',`<div class="ab-service-grid">${npc('Nielson','Embarque no continente')}${npc('Svenson','Referência de Folda')}${npc('Anderson','Referência de Senja')}${npc('Carlson','Referência de Vega')}</div><p>Nielson fica a noroeste de Carlin. Os outros NPCs têm referências nas respectivas ilhas. Escolha o nome do destino no diálogo e confira a resposta antes de confirmar a viagem; o mapa geral do arquipélago não representa um cais único.</p><div class="city-guide-links">${link('explorador/cities','Carlin','Preparar suprimentos em Carlin')}</div>`)
 +section('Hunts: compare ilha e setor',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Ice Islands clássicas · cinco hunts documentadas no catálogo</caption><thead><tr><th scope="col">Hunt</th><th scope="col">Nível sugerido</th><th scope="col">Ilha e setor</th></tr></thead><tbody>${[['carlin-folda-frost-trolls','Folda · superfície'],['carlin-folda-rotworms','Folda · cavernas'],['carlin-folda-minotaurs','Folda · setor profundo'],['carlin-senja-frost-trolls','Senja · caverna ao norte da vila'],['carlin-vega-rotworms','Vega · cavernas']].map(([id,area])=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${h.level}+</td><td>${area}</td></tr>`;}).join('')}</tbody></table></div><p>O nível sugerido de Frost Trolls não descreve os setores de Minotaurs ou a rota de uma quest. Cada ficha possui uma referência de respawn e seu próprio acesso; nenhum desses marcadores é uma rota completa desde Carlin.</p>`)
 +section('Alawar’s Vault: acesso direto ou percurso longo',`<div class="ab-access-grid">${box('SENJA','Confira a entrada pelo castelo','O guia distingue o acesso direto pelo castelo de Senja. Consulte a preparação e as etapas para escolher essa opção antes de viajar; desembarcar na ilha não equivale a chegar ao depósito.',link('quest','alawar-s-vault','Comparar os acessos de Alawar’s Vault'))}${box('FOLDA','Prepare a sequência subterrânea','A rota longa passa pelo sistema de Folda e pelas referências de chaves. Pick e Destroy Field aparecem na preparação da quest. Confira os recipientes e as portas no roteiro ilustrado antes de iniciar a descida.',link('explorador/cities','Folda','Folda · cavernas e requisitos')+link('quest','alawar-s-vault','Abrir o roteiro completo'))}</div>`)
 +section('Chaves: confira a finalidade de cada uma',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Sequência das Ice Islands · obtenção e portas nos guias individuais</caption><thead><tr><th scope="col">Chave</th><th scope="col">Função registrada</th></tr></thead><tbody><tr><th scope="row">${key('4503','Key 4503')}</th><td>Área restrita dos minotauros; coleta atrás de Fire Fields em Folda.</td></tr><tr><th scope="row">${key('4502','Key 4502')}</th><td>Portas de Alawar’s Vault; coleta ligada à sala de Dark Helmet.</td></tr><tr><th scope="row">${key('4501','Key 4501')}</th><td>Depósito de Alawar’s Vault; consulte a divergência de fontes sobre o guardião.</td></tr></tbody></table></div><p>Uma chave não substitui as outras. A ordem e a necessidade de cada etapa dependem da rota escolhida; não separe apenas pela numeração sem ler o guia de obtenção.</p>`)
 +section('Serviços registrados em Senja',`<div class="ab-service-grid">${npc('Scott','Alimentos do catálogo')}${npc('Vera','Móveis e decoração registrados')}</div><p>Abra a ficha para conferir a lista e os preços antes de contar com uma compra na ilha. Uma loja de comida ou decoração não garante a reposição de cura, mana e munição que sua expedição exige.</p>`)
 +section('Criaturas e limite histórico',creatures(['Frost Troll','Winter Wolf','Polar Bear','Rotworm','Minotaur','Minotaur Mage'])+'<p>As referências abrangem ilhas e profundidades distintas. Esta visão geral se concentra no conjunto clássico de Folda, Senja e Vega. Svargrond, Hrodmir e a quest moderna chamada The Ice Islands não foram incorporados como conteúdo do 7.4.</p>')
 +section('Checklist antes da balsa','<ul class="city-guide-checklist"><li><strong>Ilha:</strong> escolha Folda, Senja ou Vega e confira o barqueiro de retorno.</li><li><strong>Objetivo:</strong> separe hunt, visita à vila e Alawar’s Vault.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e luz; na rota da quest, leia Pick e Destroy Field.</li><li><strong>Chaves:</strong> revise 4501, 4502 e 4503 conforme o caminho escolhido.</li><li><strong>Reservas:</strong> prepare o suficiente para combater, atravessar os subsolos e voltar ao continente.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Ice Islands aqui inclui Svargrond?</summary><p>Este resumo usa as referências clássicas das ilhas Folda, Senja e Vega. A wiki atual reúne também regiões de versões posteriores, que não foram adicionadas como conteúdo do 7.4.</p></details><details><summary>O marcador geral identifica onde pegar a balsa?</summary><p>Não. Ele representa o arquipélago. Abra a ficha de Nielson para o embarque no continente ou o NPC correspondente à ilha em que você está.</p></details><details><summary>Preciso fazer Alawar’s Vault para viajar entre as ilhas?</summary><p>A viagem de balsa e a quest são objetivos separados. A sequência subterrânea e as chaves devem ser conferidas apenas quando fizerem parte da expedição escolhida.</p></details>');
 }else if(name==='Ghostlands'){
 body=section('Da superfície às cavernas profundas',`<div class="ab-access-grid">${box('01 · BASE EM CARLIN','Saia com um objetivo definido','A região fica a oeste de Carlin. Organize suprimentos na cidade e escolha se pretende caçar, visitar um NPC ou seguir uma quest. O atlas mostra uma visão geral; o mapa da hunt identifica o setor escolhido.',link('explorador/cities','Carlin','Preparar a viagem em Carlin'))}${box('02 · PRIMEIRO SUBSOLO','Skeletons e Ghouls','As duas hunts têm referências no primeiro subsolo, mas em setores próprios. Comece por um circuito curto, confira as passagens e não siga outra descida apenas porque as criaturas iniciais estão fáceis.',hunt('carlin-ghostlands-skeletons')+hunt('carlin-ghostlands-ghouls'))}${box('03 · PROFUNDIDADE','Demon Skeletons e Vampire','O catálogo aponta Demon Skeletons no andar 10 e um respawn pontual de Vampire no andar 12. Esses marcadores não são entradas nem descrevem o caminho inteiro entre a superfície e os alvos.',hunt('carlin-ghostlands-demon-skeletons')+hunt('carlin-ghostlands-vampire'))}</div>`)
 +section('Hunts: compare o setor e o preparo',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Ghostlands clássica · níveis de referência por hunt</caption><thead><tr><th scope="col">Hunt</th><th scope="col">Nível sugerido</th><th scope="col">Posição no catálogo</th></tr></thead><tbody>${[['carlin-ghostlands-skeletons','Primeiro subsolo'],['carlin-ghostlands-ghouls','Primeiro subsolo · setor próprio'],['carlin-ghostlands-demon-skeletons','Andar 10 · subsolo −3'],['carlin-ghostlands-vampire','Andar 12 · subsolo −5']].map(([id,area])=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${h.level}+</td><td>${area}</td></tr>`;}).join('')}</tbody></table></div><p>Equipamento, skills, vocação e reserva de cura mudam a segurança da caçada. Um alvo isolado pode parecer simples, mas o caminho até ele pode atravessar salas com outros inimigos e mudanças de andar.</p>`)
 +section('NPCs: ruínas, costa e profundezas',`<div class="ab-service-grid">${npc('A Ghostly Woman','Referência nas ruínas')}${npc('An Apparition','Referência nas ruínas')}${npc('Dalbrect','Acesso ligado a Isle of the Kings')}${npc('The Queen of the Banshees','NPC da quest dos sete selos')}</div><p>As posições pertencem a alturas diferentes. A Ghostly Woman e An Apparition têm referências no andar +2; Dalbrect está na superfície, e a Queen of the Banshees no andar 14. Uma ficha de NPC não é um serviço urbano disponível perto de toda hunt.</p>`)
 +section('The White Raven Monastery e a viagem à ilha',`<div class="ab-access-grid">${box('FAMILY BROOCH','Leia a obtenção antes de procurar o barco','O guia clássico registra a obtenção do Family Brooch nas cavernas de Ghostlands e sua entrega a Dalbrect para liberar o acesso à ilha. Confira essa etapa antes de sair apenas com dinheiro para transporte.',link('quest','the-white-raven-monastery','Guia de The White Raven Monastery')+link('npc','Dalbrect','Localizar Dalbrect'))}${box('OUTRO LOCAL','Isle of the Kings tem ficha própria','Depois de resolver o acesso, use a página da ilha para consultar seus NPCs e referências. A chegada ao mosteiro e a exploração de suas profundezas são objetivos distintos; confira o roteiro antes de seguir pelos subsolos.',link('explorador/cities','Isle of the Kings','Explorar Isle of the Kings'))}</div>`)
 +section('The Queen of the Banshees: planeje os sete selos',`<div class="ab-access-grid">${box('QUEST · NÍVEL 60','Os selos têm requisitos próprios','O catálogo registra nível 60, ferramentas como Rope e Pick e uma sequência de sete selos. Abra o guia completo para organizar enigmas, combates e a ordem das etapas antes da expedição.',link('quest','the-queen-of-the-banshees','Guia dos sete selos'))}${box('PREPARAÇÃO DE COMBATE','A hunt de Ghouls não cobre a quest','A expedição da Banshee envolve setores e combates diferentes das hunts de entrada. Reserve cura, mana e recursos para voltar; leia os encontros e considere a equipe indicada no roteiro.',link('npc','The Queen of the Banshees','Ficha da Queen of the Banshees'))}</div>`)
 +section('Criaturas e perigos por setor',creatures(['Skeleton','Ghoul','Demon Skeleton','Vampire','Stalker','Banshee'])+'<p>Estas referências abrangem hunts e caminhos de quests diferentes. Stalkers podem ficar invisíveis; confira recursos de combate adequados antes de explorar seus setores. Não atravesse uma sala desconhecida para fugir de um morto-vivo sem observar as passagens disponíveis.</p>')
 +(mythera?section('Mythera · Ghostland na documentação do evento',`<p>O servidor usa o nome Ghostland na referência da loja de Farmer. Consulte a ficha do evento para os diálogos e trocas de Halloween. Este roteiro clássico não descreve uma rota validada até o monumento do evento.</p><div class="city-guide-links">${link('explorador/cities','Ghostland','Ghostland · Farmer e Halloween')}</div>`):'')
 +section('Checklist antes das cavernas','<ul class="city-guide-checklist"><li><strong>Destino:</strong> escolha uma hunt, o acesso à ilha ou a quest dos selos.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel, Pick e luz conforme o roteiro.</li><li><strong>Profundidade:</strong> verifique o andar do respawn e memorize cada transição usada.</li><li><strong>Cura:</strong> prepare recursos para o percurso inteiro, incluindo inimigos invisíveis nos setores correspondentes.</li><li><strong>Quests:</strong> confira Family Brooch para o acesso com Dalbrect e os requisitos dos sete selos separadamente.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>O nível sugerido de Skeletons vale para todas as cavernas?</summary><p>Não. Cada hunt tem uma referência própria. Os setores profundos e a quest da Banshee exigem preparação diferente.</p></details><details><summary>Preciso fazer os sete selos para visitar Dalbrect?</summary><p>O catálogo apresenta objetivos separados: a referência de Dalbrect e o acesso da ilha estão no guia de The White Raven Monastery; os sete selos pertencem à quest da Queen of the Banshees.</p></details><details><summary>Ghostland e Ghostlands são duas regiões clássicas?</summary><p>O catálogo clássico tem uma ficha chamada Ghostlands. No Mythera existe também a referência Ghostland, usada na documentação da loja de Halloween. Ela é contextualizada como evento, sem duplicar o roteiro clássico.</p></details>');
 }else if(name==='Green Claw Swamp'){
 body=section('Escolha a visita antes de entrar no pântano',`<div class="ab-access-grid">${box('01 · PREPARAÇÃO','Venore como base','Organize os suprimentos em Venore antes de seguir ao pântano a noroeste. Separe ferramentas e recursos contra veneno para a rota escolhida; não conte com uma loja ao lado da entrada de cada caverna.',link('explorador/cities','Venore','Consultar Venore')+link('explorador/cities','Arredores de Venore','Comparar destinos dos arredores'))}${box('02 · CASA DE WYDA','Uma visita com andar definido','Wyda tem referência no andar +1. Sua casa e a biblioteca da Key 5000 formam um objetivo diferente da Black Knight Villa. Confira o NPC e a chave antes de procurar uma porta no pântano.',npc('Wyda','Referência da casa e dos diálogos')+key('5000','Key 5000 · biblioteca de Wyda'))}${box('03 · BLACK KNIGHT','Villa e sala subterrânea','O catálogo distingue a entrada com Key 5010, o requisito de nível 50 da quest e a hunt da sala do Black Knight. O marcador da sala fica no subsolo −4 e não é o local de coleta da chave.',link('quest','black-knight','Guia de Black Knight')+hunt('venore-black-knight'))}</div>`)
 +section('Duas chaves: confira a porta certa',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Chaves de Green Claw Swamp · funções distintas</caption><thead><tr><th scope="col">Chave</th><th scope="col">Obtenção registrada</th><th scope="col">Uso</th></tr></thead><tbody><tr><th scope="row">${key('5000','Key 5000')}</th><td>Caixão sob a casa de Wyda; confira as velas e o uso da parte superior no guia.</td><td>Pequena biblioteca da casa de Wyda.</td></tr><tr><th scope="row">${key('5010','Key 5010')}</th><td>Árvores mortas a oeste da villa. As fontes divergem em um quadrado; confira as imagens e Look.</td><td>Acesso subterrâneo da Black Knight Villa.</td></tr></tbody></table></div><p>A Key 5000 não substitui 5010. Siga o guia de obtenção da chave escolhida e confira a porta antes de entrar: o fato de ambas pertencerem ao pântano não cria uma sequência obrigatória entre elas.</p>`)
 +section('Black Knight Villa: nível de porta e combate',`<div class="ab-access-grid">${box('ACESSO · NÍVEL 50','Leia a quest antes de descer','A ficha registra Key 5010 e Rope na preparação. Confira a passagem e os requisitos no guia completo. O mapa de coleta da chave e o mapa do Black Knight representam etapas diferentes.',link('quest','black-knight','Acesso e requisitos da quest')+key('5010','Conferir a obtenção da chave'))}${box('HUNT · REFERÊNCIA 60+','Prepare a sala do cavaleiro','A hunt tem nível sugerido 60 e aponta a sala no subsolo −4. Essa indicação não garante segurança: confira equipamento, skills e cura antes de enfrentar o cavaleiro ou repetir a caçada.',hunt('venore-black-knight'))}</div>`)
 +section('Blood Herb: coleta e troca com Wyda',`<div class="ab-access-grid">${box('COLETA','Ferramentas e perigo no caminho','O guia clássico registra Rope, Shovel e Machete. Confira a árvore e o caminho no roteiro; prepare-se para a referência de Giant Spider na aproximação. O nível zero de porta não transforma a coleta em uma viagem segura para iniciantes.',link('quest','blood-herb','Guia de Blood Herb'))}${box('TROCA','Consulte o diálogo de Wyda','A referência clássica liga Blood Herb à troca por Witchesbroom. Confira o item que pretende entregar e acompanhe a resposta do NPC. Recompensas de eventos e alterações posteriores da wiki atual não foram adicionadas como regras do 7.4.',link('npc','Wyda','Abrir ficha de Wyda'))}</div>`)
 +section('Outras quests: escolha um roteiro próprio',`<div class="ab-access-grid">${box('VOODOO DOLL','Setor ao norte do pântano','O guia reúne o objetivo da boneca e da Magic Light Wand em um percurso próprio. Consulte as descidas e os encontros antes de ir; não use o acesso da villa como caminho para essa recompensa.',link('quest','voodoo-doll','Guia de Voodoo Doll'))}${box('SILVER BROOCH','Referência histórica em revisão','A ficha Silver Brooch ainda tem status histórico incerto no catálogo. Ela pode ser consultada com essa ressalva, sem apresentar a recompensa como conteúdo clássico confirmado.',link('quest','silver-brooch','Consultar status de Silver Brooch'))}</div>`)
 +section('Criaturas e ferramentas para o percurso',creatures(['Poison Spider','Scorpion','Wasp','Witch','Giant Spider','Black Knight'])+'<p>Os nomes abrangem destinos diferentes do pântano e suas quests. Veneno e inimigos à distância podem atrapalhar o retorno. Machete serve para os trechos de vegetação indicados no roteiro; não presuma que a mesma ferramenta abra buracos ou portas.</p>')
 +section('Checklist antes de sair de Venore','<ul class="city-guide-checklist"><li><strong>Objetivo:</strong> escolha Wyda, biblioteca, Blood Herb, Voodoo Doll ou Black Knight.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel, Machete e luz conforme o guia do destino.</li><li><strong>Veneno:</strong> reserve cura e recursos para remover Poison durante a ida e a volta.</li><li><strong>Chave:</strong> separe 5000 ou 5010 pela porta que pretende usar.</li><li><strong>Combate:</strong> confira o risco de Giant Spider e Black Knight quando estiverem no seu percurso.</li><li><strong>Andar:</strong> distinga a casa de Wyda no +1 da sala do cavaleiro no subsolo −4.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>A Key 5000 abre a Black Knight Villa?</summary><p>Não. A biblioteca de Wyda usa a Key 5000; o acesso subterrâneo da villa está ligado à Key 5010.</p></details><details><summary>O marcador geral do pântano é uma entrada subterrânea?</summary><p>O atlas utiliza uma referência de visão geral no andar +1, ligada à região de Wyda. Para a villa e cada quest, abra o mapa do próprio guia.</p></details><details><summary>Os bosses e eventos da wiki atual estão incluídos?</summary><p>Este resumo usa as quests e hunts clássicas revisadas. Sistemas, invasões e criaturas posteriores não foram apresentados como conteúdo do 7.4.</p></details>');
 }else if(name==='Ghostland'){
 body=section('Farmer: referência sazonal do Mythera',`<div class="ab-access-grid">${box('LOCALIZAÇÃO PUBLICADA','Sala a oeste de Ghostland','A documentação do Halloween situa Farmer em uma pequena sala a oeste de Ghostland, perto do monumento relacionado ao Hollow Harvester. Consulte o guia oficial para reconhecer o local; a biblioteca não possui coordenadas validadas desse acesso.',link('npc','Farmer','Farmer · localização e trocas'))}${box('LOJA DO EVENTO','Compre por diálogo','Farmer não utiliza janela de trade. Use offer para consultar as opções, diga o item desejado e confirme yes após conferir a proposta. Quantidades podem ser informadas antes do nome.',link('mundo/guia','events-new--halloween-2026--halloween-npc-store','Guia da loja de Halloween'))}${box('PLANEJAMENTO','Separe evento e roteiro clássico','Para as cavernas e quests da região clássica, abra Ghostlands. Esta ficha mantém o nome usado na documentação do evento e não apresenta uma rota validada entre os marcadores clássicos e a sala de Farmer.',link('explorador/cities','Ghostlands','Ghostlands · hunts e quests clássicas'))}</div>`)
 +section('Moeda e itens da loja',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Exemplos de trocas · Halloween Coins, não gp</caption><thead><tr><th scope="col">Item</th><th scope="col">Halloween Coins</th></tr></thead><tbody>${(window.MYTHERA_DOMAIN?.npcs?.find(n=>n.name==='Farmer')?.offers||[]).map(o=>`<tr><th scope="row">${esc(o.item)}</th><td>${o.price.toLocaleString('pt-BR')}</td></tr>`).join('')}</tbody></table></div><p>Antes de confirmar, confira a moeda, a quantidade e o item na resposta do NPC. Prepare espaço e capacidade: a documentação alerta que uma entrega sem espaço ou cap pode ficar no chão.</p><div class="city-guide-links">${link('npc','Farmer','Consultar ofertas de Farmer')}${link('mundo/guia','events-new--halloween-2026--halloween-npc-store','Ver a loja completa')}</div>`)
 +section('Dreadhorn: prepare uma etapa por vez',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Ordem publicada do outfit do evento</caption><thead><tr><th scope="col">Etapa</th><th scope="col">Bags</th><th scope="col">Golden Pumpkin</th><th scope="col">Golden Skull</th></tr></thead><tbody><tr><th scope="row">Base</th><td>5</td><td>0</td><td>0</td></tr><tr><th scope="row">Primeiro addon</th><td>10</td><td>1</td><td>1</td></tr><tr><th scope="row">Segundo addon</th><td>10</td><td>1</td><td>1</td></tr><tr><th scope="row">Total</th><td>25</td><td>2</td><td>2</td></tr></tbody></table></div><p>Use outfit para a base e addon para os complementos, respeitando a sequência. Se comprar todas as 25 Stuffed Halloween Bags na loja por 5.000 moedas cada, o custo das bags será de <strong>125.000 Halloween Coins</strong>, além dos dois Golden Pumpkins e dois Golden Skulls.</p><div class="city-guide-links">${link('mundo/guia','events-new--halloween-2026--halloween-npc-store','Conferir etapas e materiais')}</div>`)
 +section('Objetivos diferentes no evento',`<div class="ab-access-grid">${box('TROCAS','Escolha a compra antes do diálogo','Organize os materiais do objetivo desejado. Comprar anéis, trocar uma caixa e solicitar o outfit são ações diferentes. Confirme o nome da oferta para não gastar moedas destinadas a outra etapa.',link('npc','Farmer','Rever ofertas e palavras-chave'))}${box('COMBATE','Hollow Harvester tem guia próprio','A referência ao monumento não significa que comprar na loja complete o acesso de um desafio. Leia o guia do Hollow Harvester antes de preparar uma expedição de combate.',link('mundo/guia','events-new--halloween-2026--hollow-harvester','Hollow Harvester · guia do evento'))}${box('COLETA','Gravepaw e moedas','Se pretende juntar moedas antes de visitar a loja, consulte as regras e os locais anunciados no guia de Gravepaw. Esta página não apresenta um alerta de aparição ao vivo.',link('mundo/guia','events-new--halloween-2026--gravepaw-raids','Gravepaw · regras e locais'))}</div>`)
 +section('Checklist antes da troca','<ol class="city-guide-checklist"><li><strong>Objetivo:</strong> escolha item da loja, outfit ou consulta de diálogo.</li><li><strong>Moeda:</strong> confira seu saldo de Halloween Coins e preserve o valor necessário para a etapa seguinte.</li><li><strong>Materiais:</strong> confira bags, Golden Pumpkins e Golden Skulls antes de pedir addons.</li><li><strong>Capacidade:</strong> mantenha espaço na mochila e capacidade para receber a entrega.</li><li><strong>Confirmação:</strong> leia a proposta de Farmer antes de responder yes, especialmente em compras de várias unidades.</li><li><strong>Acesso:</strong> reconheça o caminho no servidor; o atlas clássico não valida a rota até o monumento.</li></ol>')
 +section('Dúvidas rápidas','<details><summary>Essa loja existe no clássico?</summary><p>Esta ficha aparece somente no Mythera e descreve o Halloween de 2026. Não adiciona Farmer ou as trocas de Halloween à base clássica.</p></details><details><summary>O nome Ghostland cria uma segunda dungeon clássica?</summary><p>Não. É o nome usado na documentação do evento para a referência da loja. Ghostlands mantém o roteiro das cavernas e quests clássicas em sua própria ficha.</p></details><details><summary>Os preços são em gold coins?</summary><p>As trocas apresentadas aqui usam Halloween Coins. Confira a moeda informada na oferta antes de confirmar a compra.</p></details><details><summary>A página informa se Farmer está disponível agora?</summary><p>Ela documenta a referência sazonal publicada. A disponibilidade deve ser conferida no servidor; não há consulta em tempo real nesta ficha.</p></details>');
 }else if(name==='Fields of Glory'){
 body=section('Reconheça a região antes de descer',`<div class="ab-access-grid">${box('01 · BASE','Prepare a saída em Carlin','Use Carlin para organizar cura, comida e munição. O atlas de Fields of Glory abre uma visão geral da região; para uma caverna ou quest, confira o mapa do objetivo antes de sair da superfície.',link('explorador/cities','Carlin','Serviços e preparação em Carlin'))}${box('02 · SUPERFÍCIE','Campos ao norte e nordeste','A região se estende na direção de Northport. Observe os caminhos de volta a Carlin e não interprete a presença de criaturas fracas na superfície como indicação de segurança para todas as descidas.',link('explorador/cities','Northport','Northport · referência da costa'))}${box('03 · ORIENTAÇÃO','Marque a entrada e o andar','Antes de entrar em uma caverna, confira se o marcador representa a entrada ou apenas um respawn. Leve recursos para subir e descer; mantenha uma referência do ponto pelo qual entrou.',link('explorador/cities','Carlin','Escolher um destino documentado'))}</div>`)
 +section('NPCs registrados na base clássica',`<div class="ab-service-grid">${npc('Aneus','Referência de diálogo na região')}${npc('Humphrey','Serviço de bênção registrado')}</div><p>O catálogo associa Aneus e Humphrey a Fields of Glory. Aneus possui referência na superfície; Humphrey tem posição registrada no andar +1. Abra a ficha para conferir a localização e o serviço antes de viajar.</p><p>O serviço de bênção de Humphrey aparece por 10.000 gp na base comunitária 7.4. Confira a resposta do NPC e as regras do servidor antes de confirmar: uma referência do catálogo não informa quais proteções seu personagem já possui.</p>`)
 +section('Hunts próximas: escolha uma ficha própria',`<div class="ab-access-grid">${box('REGIÃO DE CARLIN','Rotworms e acampamento de Amazons','O catálogo oferece fichas separadas para essas caçadas. Use os mapas delas para escolher o destino: estes links são alternativas na região de Carlin, não uma afirmação de que os dois respawns ficam no marcador geral de Fields of Glory.',hunt('rotworm-carlin')+hunt('carlin-amazon'))}${box('OUTRO DESTINO','Cemitério de Carlin','O cemitério tem uma referência própria de Trolls. Se esse for o seu objetivo, siga a ficha específica e observe o subsolo indicado; o ponto das planícies não substitui a entrada da caverna.',hunt('carlin-graveyard'))}</div><p>Fields of Glory ainda não tem uma hunt própria associada no catálogo revisado. As opções acima preservam seus nomes e localizações originais, para que você possa escolher uma expedição documentada sem misturar os setores.</p>`)
 +section('Criaturas: prepare o combate pelo destino',creatures(['Wolf','Bear','Troll','Rotworm','Amazon','Valkyrie','Witch'])+'<p>Estas fichas ajudam a comparar criaturas da região e das caçadas próximas apresentadas acima; não descrevem um único grupo no marcador de Fields of Glory. Confira ataques e equipamento antes de sair de uma caçada simples para um acampamento com inimigos à distância.</p>')
 +section('Subsolo e quests com referências separadas',`<div class="ab-access-grid">${box('EXPLORAÇÃO','Um buraco não identifica a quest','Não desça seguindo apenas o nome da planície. Abra o guia do objetivo para conferir ferramentas, nível e retorno. O catálogo não associa uma chave numerada própria a Fields of Glory.',link('explorador/cities','Carlin','Consultar quests e regiões de Carlin'))}${box('DEMONA E LABIRINTOS','Confira o status histórico','A ficha Demona Ring permanece em revisão histórica no catálogo. A associação de uma região a um labirinto não confirma a recompensa nem transforma o ponto da superfície em uma rota validada até Demona.',link('quest','demona-ring','Consultar status de Demona Ring'))}</div>`)
 +section('Checklist antes de explorar','<ul class="city-guide-checklist"><li><strong>Destino:</strong> escolha visita a NPC, travessia de superfície ou uma hunt específica.</li><li><strong>Andar:</strong> confira o +1 de Humphrey e as profundidades das cavernas escolhidas.</li><li><strong>Ferramentas:</strong> prepare Rope, Shovel e luz conforme o acesso pretendido.</li><li><strong>Suprimentos:</strong> leve cura, comida, munição e recursos contra veneno para o percurso.</li><li><strong>Volta:</strong> registre a entrada da caverna e mantenha o caminho de Carlin como referência.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Fields of Glory é uma cidade com depot?</summary><p>A ficha descreve uma região ao redor de Carlin. Use a cidade como base de preparação e consulte os NPCs individualmente para saber qual serviço está registrado.</p></details><details><summary>O mapa leva até Demona?</summary><p>O atlas abre a referência geral da superfície. Uma expedição a labirintos e setores profundos exige roteiro próprio; o marcador não calcula esse caminho.</p></details><details><summary>As quests de outfits da wiki atual estão incluídas?</summary><p>Este resumo mantém os registros clássicos revisados e o status histórico de cada quest. Sistemas e missões posteriores não foram acrescentados como conteúdo do 7.4.</p></details>');
 }else if(name==='Folda'){
 body=section('Balsa, ilha e retorno',`<div class="ab-access-grid">${box('01 · CONTINENTE','Embarque com Nielson','A balsa de Nielson fica a noroeste de Carlin. Prepare os suprimentos antes de embarcar e escolha Folda no diálogo. A ficha do barqueiro distingue a referência de embarque do respawn de uma hunt.',npc('Nielson','Balsa no continente'))}${box('02 · FOLDA','Localize Svenson na chegada','Svenson é a referência de transporte em Folda. Consulte sua ficha e identifique o local de retorno antes de entrar nas cavernas; a posição do atlas da ilha não descreve o trajeto até cada subsolo.',npc('Svenson','Balsa e retorno'))}${box('03 · OUTRAS ILHAS','Senja e Vega são destinos distintos','A rede das Ice Islands também envolve Senja e Vega. Confira o destino pedido ao barqueiro antes de confirmar a viagem. A rota longa de Alawar’s Vault não equivale a uma simples travessia de balsa.',link('explorador/cities','Senja','Consultar Senja')+link('explorador/cities','Vega','Consultar Vega'))}</div>`)
 +section('Escolha a profundidade da hunt',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Folda clássica · três setores do catálogo</caption><thead><tr><th scope="col">Hunt</th><th scope="col">Nível sugerido</th><th scope="col">Referência</th></tr></thead><tbody>${[['carlin-folda-frost-trolls','Superfície'],['carlin-folda-rotworms','Cavernas da ilha'],['carlin-folda-minotaurs','Setor profundo · andar 10']].map(([id,area])=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${h.level}+</td><td>${area}</td></tr>`;}).join('')}</tbody></table></div><p>Os níveis servem de referência para cada alvo. A hunt de Frost Trolls na superfície não descreve os riscos da exploração profunda; confira os acessos e preserve cura para o caminho de volta.</p>`)
 +section('Chaves das Ice Islands: três funções diferentes',`<div class="ab-access-grid">${box('KEY 4503','Passagem para o setor dos minotauros','A coleta registrada fica em um baú atrás de Fire Fields no primeiro subsolo de Folda. Consulte o uso de Destroy Field antes de atravessar a área; a chave dá acesso ao setor restrito dos minotauros.',key('4503','Key 4503 · imagens e obtenção'))}${box('KEY 4502','Sala de Dark Helmet e acesso de Alawar','O roteiro registra um baú sudoeste na sala de Dark Helmet, com Minotaur Mage, e preparação com 4503, Destroy Field e Pick. Esta etapa tem guia próprio: não use o marcador de Minotaurs como localização exata do recipiente.',key('4502','Key 4502 · caminho e porta'))}${box('KEY 4501','Depósito de Alawar’s Vault','A coleta está ligada ao percurso de Folda e ao depósito da quest. O guia ilustrado registra a divergência entre fontes sobre o guardião da sala; siga a descrição e as imagens do roteiro em conjunto.',key('4501','Key 4501 · coleta e divergência'))}</div>`)
 +section('Alawar’s Vault: escolha a rota antes de viajar',`<div class="ab-access-grid">${box('ROTA LONGA','Folda faz parte do percurso','O guia da quest distingue a rota longa por Folda do acesso direto pelo castelo de Senja. Abra o roteiro completo antes de escolher ferramentas e chaves; estar em Folda não significa estar na sala da recompensa.',link('quest','alawar-s-vault','Alawar’s Vault · guia completo'))}${box('PREPARAÇÃO','Ferramentas para as etapas','A preparação registrada inclui Pick e Destroy Field. Confira também as chaves usadas na rota escolhida. Não entre em campos ou passagens profundas contando apenas com equipamento de uma caçada de Frost Trolls.',key('4503','Conferir a primeira passagem')+link('quest','alawar-s-vault','Comparar os acessos da quest'))}</div>`)
 +section('Criaturas: superfície e cavernas',creatures(['Frost Troll','Winter Wolf','Polar Bear','Rotworm','Minotaur','Minotaur Archer','Minotaur Guard','Minotaur Mage'])+'<p>A lista reúne referências de exploração e da sequência de chaves, em locais diferentes. Os ataques à distância de Minotaur Archer e Minotaur Mage exigem mais preparo que os Frost Trolls; confira o setor antes de avançar para outra sala.</p>')
 +section('Checklist antes da balsa','<ul class="city-guide-checklist"><li><strong>Transporte:</strong> localize Nielson no continente e Svenson em Folda.</li><li><strong>Objetivo:</strong> escolha superfície, cavernas ou a rota de Alawar’s Vault.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e luz; para as etapas documentadas da quest, prepare Pick e Destroy Field.</li><li><strong>Chaves:</strong> separe 4503, 4502 e 4501 conforme o roteiro, observando a função de cada uma.</li><li><strong>Retorno:</strong> preserve recursos para atravessar os subsolos e voltar ao embarque.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Preciso de chaves para caçar Frost Trolls na superfície?</summary><p>As chaves acima estão ligadas a setores restritos e à sequência de Alawar’s Vault. A ficha de Frost Trolls possui objetivo e referência próprios, sem exigir que você faça a quest inteira.</p></details><details><summary>Todo conteúdo da wiki atual pertence ao 7.4?</summary><p>Não. Este resumo utiliza as hunts e guias clássicos revisados; criaturas e reformas posteriores não foram transportadas da wiki atual para a ilha clássica.</p></details><details><summary>A balsa é o mesmo caminho subterrâneo até Senja?</summary><p>Não. Viajar entre ilhas com o barqueiro e seguir a rota longa da quest são percursos distintos. Confira o guia da recompensa antes de escolher o trajeto.</p></details>');
 }else if(name==='Frostveil'){
 const eirik=window.MYTHERA_DOMAIN?.npcs?.find(n=>n.name==='Eirik');
 const offers=eirik?.offers||[];
 body=section('Planeje a visita pelo serviço',`<div class="ab-access-grid">${box('COMÉRCIO','Eirik compra loot','O catálogo comunitário associa Eirik a Frostveil e registra os itens que ele compra do jogador. Abra sua ficha para comparar as ofertas e separar os equipamentos que pretende vender.',link('npc','Eirik','Abrir Eirik · compras e preços'))}${box('LOCALIZAÇÃO','Confira o acesso dentro do servidor','As referências disponíveis não publicam uma rota validada nem coordenadas de Eirik. Esta página não oferece um marcador de outra cidade como se fosse Frostveil. Confirme no jogo o embarque, a chegada e o retorno antes de transportar loot pesado.',link('npc','Eirik','Consultar a referência do NPC'))}${box('EVENTO','Frostveil Cemetery','A documentação de Gravepaw inclui Frostveil Cemetery na lista de locais anunciados. Trata-se de uma referência ao cemitério no evento de Halloween, sem confirmar um local de aparição ativo neste momento.',link('mundo/guia','events-new--halloween-2026--gravepaw-raids','Gravepaw · locais e comportamento'))}</div>`)
 +section('Venda de loot: confira o sentido da oferta',`<p><strong>Eirik compra de você.</strong> Os valores abaixo são referências comunitárias em gp. Eles não representam o preço para comprar o equipamento do NPC nem uma cotação ao vivo do servidor.</p><div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Exemplos de ofertas de Eirik · fonte comunitária OTLab</caption><thead><tr><th scope="col">Item</th><th scope="col">NPC paga</th></tr></thead><tbody>${['Ancient Amulet','Beholder Helmet','Frozen Shield','Frozen Slayer','Demon Shield','Dragon Scale Mail','Golden Armor','Mastermind Shield','Magic Plate Armor'].map(name=>{const o=offers.find(o=>o.item===name);return o?`<tr><th scope="row">${esc(o.item)}</th><td>${o.price.toLocaleString('pt-BR')} gp</td></tr>`:'';}).join('')}</tbody></table></div><div class="city-guide-links">${link('npc','Eirik','Consultar todas as ofertas de Eirik')}</div><p>Confira nome, quantidade e resposta do NPC antes de confirmar a venda. Equipamentos com nomes parecidos podem ter valores e compradores diferentes. A ficha completa mantém a fonte de cada oferta para consulta.</p>`)
 +section('Gravepaw: cemitério e evento sazonal',`<div class="ab-access-grid">${box('LOCAIS ANUNCIADOS','Uma lista não é um alerta ao vivo','Frostveil Cemetery aparece entre os cemitérios e regiões anunciados para as invasões do evento. A fonte não publica horário garantido, coordenadas ou rota até o cemitério. Consulte o guia para entender o comportamento das criaturas e o loot do evento.',link('mundo/guia','events-new--halloween-2026--gravepaw-raids','Abrir guia de Gravepaw'))}${box('OUTRO OBJETIVO','Comércio e evento são visitas diferentes','A associação de Eirik a Frostveil não prova que ele esteja dentro do cemitério nem que o caminho entre os dois locais esteja documentado. Prepare separadamente a venda de equipamentos e a participação no evento.',link('npc','Eirik','Planejar a venda de loot'))}</div>`)
 +section('O que está documentado para a visita',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Referências disponíveis de Frostveil</caption><thead><tr><th scope="col">Informação</th><th scope="col">Referência</th></tr></thead><tbody><tr><th scope="row">Eirik associado a Frostveil</th><td>Catálogo comunitário OTLab</td></tr><tr><th scope="row">Itens e preços de compra</th><td>Ofertas comunitárias na ficha de Eirik</td></tr><tr><th scope="row">Frostveil Cemetery no evento</th><td>Documentação oficial de Gravepaw</td></tr><tr><th scope="row">Rota, coordenadas e transporte</th><td>Ainda sem referência validada nesta biblioteca</td></tr><tr><th scope="row">Depot, templo, hunts e chaves locais</th><td>Ainda sem documentação suficiente nesta biblioteca</td></tr></tbody></table></div><p>Use as informações disponíveis para escolher o objetivo da viagem. Serviços não descritos nesta ficha precisam ser conferidos no servidor; sua ausência na biblioteca não significa que não existam no jogo.</p>`)
 +section('Checklist antes de levar seu loot','<ol class="city-guide-checklist"><li><strong>Confira o comprador:</strong> abra Eirik e verifique se o equipamento aparece entre as compras do NPC.</li><li><strong>Compare os valores:</strong> consulte o preço comunitário como referência e confirme o valor apresentado dentro do jogo.</li><li><strong>Organize a carga:</strong> separe os itens por nome e preserve capacidade e suprimentos para a viagem.</li><li><strong>Valide o acesso:</strong> identifique o caminho de ida e volta no Mythera antes de transportar vários equipamentos.</li><li><strong>Evento:</strong> se pretende procurar Gravepaw, leia o guia sazonal; a lista de cemitérios não informa uma invasão ativa.</li></ol>')
 +section('Dúvidas rápidas','<details><summary>Frostveil faz parte do Tibia 7.4 clássico?</summary><p>Esta ficha aparece somente com Mythera selecionado. Ela descreve o local próprio do servidor e não acrescenta Frostveil ao mapa clássico.</p></details><details><summary>O preço de Eirik é garantido em tempo real?</summary><p>Não. São ofertas de uma fonte comunitária. Confirme o preço e o item no diálogo do NPC antes da transação.</p></details><details><summary>Onde está o mapa para chegar?</summary><p>A biblioteca ainda não possui uma rota ou coordenada validada nas referências disponíveis. Não foi atribuído um ponto clássico de outra região ao local.</p></details>');
 }else if(name==='Elvenbane'){
 body=section('Do acesso subterrâneo à torre',`<div class="ab-access-grid">${box('01 · PREPARAÇÃO','Ab’Dendriel é sua base','Reabasteça antes de partir para oeste. Elvenbane é um castelo ocupado por criaturas: não planeje comprar cura ou vender loot durante a exploração. Escolha a hunt pelo setor e confira o caminho de volta.',link('explorador/cities',"Ab'Dendriel",'Serviços de Ab’Dendriel'))}${box('02 · ENTRADA','A caverna leva à ilha','O acesso clássico fica próximo de 32579,31679,7. A travessia subterrânea chega ao calabouço; o marcador geral do castelo não é a entrada da caverna. Consulte a ficha dos Minotaurs para distinguir o subsolo da superfície.',hunt('abdendriel-elvenbane-minotaurs'))}${box('03 · PÁTIO','Orcs na superfície','Depois do subsolo, o pátio tem uma referência própria de Orc Warriors. Limpe a aproximação das escadas e evite avançar em vários grupos ao mesmo tempo; preserve o acesso usado na chegada.',hunt('abdendriel-elvenbane-orcs'))}${box('04 · TORRE','Subir também aumenta o risco','A torre tem uma referência de Dragon no +2 e de Demon Skeleton no +4. São destinos diferentes do pátio; subir em busca de uma recompensa pode obrigar você a atravessar setores mais perigosos.',hunt('abdendriel-elvenbane-dragon')+hunt('abdendriel-elvenbane-demon-skeleton'))}</div>`)
 +section('Escolha o andar antes de abrir o mapa',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Setores clássicos de Elvenbane · níveis sugeridos para cada hunt</caption><thead><tr><th scope="col">Destino</th><th scope="col">Andar</th><th scope="col">Nível de referência</th></tr></thead><tbody>${[['abdendriel-elvenbane-minotaurs','Subsolo −1'],['abdendriel-elvenbane-orcs','Superfície'],['abdendriel-elvenbane-dragon','Torre +2'],['abdendriel-elvenbane-demon-skeleton','Torre +4']].map(([id,floor])=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${floor}</td><td>${h.level}+</td></tr>`;}).join('')}</tbody></table></div><p>O nível de referência depende de skills, equipamento, vocação e cura. Uma indicação menor para Demon Skeleton não torna a subida mais simples: planeje também os encontros nos andares anteriores.</p>`)
 +section('Criaturas e combate em passagens estreitas',creatures(['Minotaur','Orc Warrior','Orc Shaman','Minotaur Mage','Elf Arcanist','Dragon','Demon Skeleton'])+'<p>Os nomes acima abrangem setores distintos do castelo. Nas escadas, confira espaço para recuar e cure-se antes de mudar de andar. Contra Dragon, evite permanecer na frente do ataque de fogo; para inimigos à distância, não recue para uma sala ainda ocupada.</p>')
 +section('Quest e recompensas: referência em revisão',`<aside class="city-guide-notice"><strong>Elvenbane Quest · confirmação histórica pendente</strong><p>Existe uma ficha de Elvenbane no catálogo, mas sua data de introdução ainda não está suficientemente documentada para confirmar todos os detalhes no 7.4. Ela permanece em revisão; a presença do castelo e das hunts na base comunitária não confirma automaticamente as recompensas da quest.</p><p>Se seu objetivo for a quest, confira o status e os requisitos na ficha antes de partir. Não use potions modernas como referência para o fluido de mana clássico.</p><div class="city-guide-links">${link('quest','elvenbane','Consultar ficha e status histórico')}</div></aside>`)
 +section('Checklist da expedição','<ul class="city-guide-checklist"><li><strong>Objetivo:</strong> escolha Minotaurs, pátio ou um andar específico da torre.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e luz conforme o acesso; consulte Destroy Field no roteiro da quest.</li><li><strong>Reservas:</strong> prepare cura, mana, comida e munição para ida, combate e volta.</li><li><strong>Escadas:</strong> não suba com pouca vida nem use outro andar como fuga sem conhecer as criaturas.</li><li><strong>Retorno:</strong> memorize a passagem entre calabouço e continente antes de prolongar a exploração.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Posso chegar de barco?</summary><p>O acesso desta referência clássica passa pela caverna subterrânea a oeste de Ab’Dendriel. O ponto do atlas mostra o castelo; ele não é um cais.</p></details><details><summary>É uma única hunt de nível 20?</summary><p>Não. O subsolo, o pátio e a torre possuem fichas e níveis próprios. A preparação dos Minotaurs não cobre o Dragon dos andares superiores.</p></details><details><summary>Preciso das chaves de Draconia?</summary><p>Elvenbane e Draconia são destinos diferentes. Este resumo não associa as chaves 3001–3008 ao castelo de Elvenbane; consulte a ficha do objetivo antes de separar chaves.</p></details>');
 }else if(name==="Eremo's Island"){
 body=section('Organize a visita em três etapas',`<div class="ab-access-grid">${box('01 · CHEGADA','Comece em Cormaya','Procure Pemaret no embarque de Cormaya e peça a viagem para Eremo. Consulte a posição na ficha do barqueiro; não confunda esse embarque com o steamship de Gurbasch no subsolo.',npc('Pemaret','Barco para Eremo')+link('explorador/cities','Cormaya','Consultar Cormaya'))}${box('02 · ATENDIMENTO','Encontre o sábio na ilha','A ficha de Eremo reúne sua posição, os itens negociados e as magias da base clássica. Defina se quer comprar um amuleto, vender um item aceito ou aprender uma magia antes de iniciar o diálogo.',npc('Eremo','Itens mágicos e ensino de magias'))}${box('03 · RETORNO','Fale com Eremo para voltar','As referências de diálogo registram Cormaya, back, teleport ou Tibia para pedir a volta, com confirmação yes quando solicitada. Leia a resposta do NPC para confirmar o destino antes de aceitar.',link('explorador/cities','Cormaya','Preparar a continuação da viagem'))}</div>`)
 +section('Amulet of Loss: compra com objetivo definido',`<div class="ab-access-grid">${box('COMPRA CLÁSSICA','Reserve 50.000 gp para o AoL','O catálogo clássico registra o Amulet of Loss à venda por 50.000 gp. Confira o item e o sentido da oferta na ficha: a lista de compra do NPC é diferente da lista do que ele vende ao jogador.',link('npc','Eremo','Ver preços e itens de Eremo'))}${box('OUTRO ITEM','Broken Amulet não é um AoL novo','O catálogo registra uma oferta de compra de Broken Amulet por Eremo. Isso é uma negociação distinta da compra de Amulet of Loss. Abra a ficha para confirmar exatamente qual item você está levando.',link('npc','Eremo','Conferir a oferta de compra'))}</div><p>Este guia ajuda a localizar o serviço. Para decidir a proteção do personagem, confira as regras de morte, amuletos e bênçãos do servidor em que joga antes de gastar o dinheiro.</p>`)
 +section('Magias registradas na base 7.4',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Ensino de Eremo · consulte os requisitos na ficha da magia</caption><thead><tr><th scope="col">Magia</th><th scope="col">Preço registrado</th></tr></thead><tbody>${['Challenge','Conjure Power Bolt','Enchant Staff','Wild Growth'].map(name=>{const n=C.npcs.find(n=>n.name==='Eremo');const offer=n.spellOffers.find(o=>o.name===name);return `<tr><th scope="row">${esc(name)}</th><td>${offer.price.toLocaleString('pt-BR')} gp</td></tr>`;}).join('')}</tbody></table></div><p>O preço da aula não substitui os requisitos de vocação, promoção, acesso ou recursos da magia. Use a ficha de Eremo e a biblioteca de magias para conferir o que seu personagem pode aprender. As magias de versões posteriores da wiki atual não foram acrescentadas a esta lista.</p><div class="city-guide-links">${link('npc','Eremo','Consultar ensino de magias')}${link('catalog','magias','Abrir biblioteca de magias')}</div>`)
 +section('Ilha de serviços: escolha onde continuar',`<div class="ab-access-grid">${box('SEM HUNT PRÓPRIA NO CATÁLOGO','A visita tem foco no NPC','A base revisada não associa uma hunt ou quest própria à Eremo’s Island. Não use o marcador de Eremo como entrada para Hero Cave, Cyclopolis ou qualquer caverna de Edron.',link('explorador/cities','Edron','Escolher uma hunt em Edron'))}${box('CONEXÃO COM CORMAYA','Volte antes de mudar de transporte','Cormaya reúne os embarques relacionados à visita. Se o próximo destino é Edron ou Kazordoon, confira o transporte na página da ilha e siga até o NPC correto.',link('explorador/cities','Cormaya','Ver embarques e serviços'))}</div>`)
 +section('Checklist antes de embarcar','<ul class="city-guide-checklist"><li><strong>Dinheiro:</strong> separe o custo do serviço desejado e confira a resposta do NPC antes de confirmar a compra.</li><li><strong>Item certo:</strong> distinga Amulet of Loss de Broken Amulet na oferta.</li><li><strong>Magia:</strong> confira requisitos do personagem e preço da aula na referência clássica.</li><li><strong>Volta:</strong> use o diálogo de Eremo e confirme o retorno antes de organizar a próxima viagem.</li><li><strong>Servidor:</strong> no Mythera, confira as regras próprias; a lista acima representa a base 7.4.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Eremo fica no centro de Edron?</summary><p>Não. Ele mora em uma pequena ilha ligada à região de Edron. O embarque para a visita é feito com Pemaret em Cormaya.</p></details><details><summary>Posso embarcar com Gurbasch?</summary><p>Gurbasch é a referência do steamship subterrâneo de Cormaya. A visita a Eremo usa Pemaret; são NPCs e serviços diferentes.</p></details><details><summary>Todas as magias e bênçãos da wiki atual existem aqui?</summary><p>Este resumo lista somente as quatro magias registradas no catálogo clássico. Não apresenta serviços posteriores como confirmados no 7.4 e não atribui regras exclusivas de um servidor a todos os outros.</p></details>');
 }else if(name==='Fibula'){
 body=section('Da vila à dungeon: escolha seu objetivo',`<div class="ab-access-grid">${box('01 · CHEGADA','Passagem a sudoeste de Thais','O acesso à ilha é subterrâneo, pela região a sudoeste de Thais. Confira a entrada no guia de Deeper Fibula; o centro da vila no atlas não marca o início dessa passagem. Reabasteça na cidade antes de viajar.',link('explorador/cities','Thais','Preparar suprimentos em Thais')+link('quest','fibula','Guia ilustrado de Deeper Fibula'))}${box('02 · VILA','Serviços locais antes da descida','Na superfície, consulte Dermot e Simon para a chave da dungeon e Timur para os equipamentos registrados. Uma visita à vila não exige atravessar a parte profunda da caverna.',npc('Timur','Equipamentos do catálogo'))}${box('03 · DUNGEON','Key 3940 abre o acesso','Separe a chave antes de descer. O catálogo distingue a compra direta com Dermot da alternativa de diálogo com Simon The Beggar. O guia da chave reúne a obtenção e a porta correspondente.',key('3940','Key 3940 · obtenção e uso'))}${box('04 · DEEPER FIBULA','A porta de nível 50 não mede a dificuldade','Depois da porta e do teleporte, não conte com voltar pela mesma entrada. Planeje o percurso completo, a Key 3980 e os encontros de Dragons e Dragon Lords antes de atravessar.',link('quest','fibula','Requisitos, caminho e saída'))}</div>`)
 +section('NPCs e compra da chave',`<div class="ab-service-grid">${npc('Dermot','Key 3940 · compra direta')}${npc('Simon The Beggar','Key 3940 · alternativa por diálogo')}${npc('Timur','Armas e equipamentos')}${npc('Eddy','Ficha e localização')}</div><p>A Key 3940 custa <strong>2.000 gp com Dermot</strong>. A alternativa documentada com Simon totaliza <strong>800 gp, em etapas de 100 + 500 + 200</strong>, pelo diálogo de ajuda. Siga o guia ilustrado para acompanhar as respostas: não confunda uma doação isolada com a entrega da chave.</p><div class="city-guide-links">${key('3940','Abrir diálogo e imagens da Key 3940')}</div>`)
 +section('Hunts por setor e preparo',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Fibula e Deeper Fibula · níveis de referência para combate</caption><thead><tr><th scope="col">Setor</th><th scope="col">Nível sugerido</th><th scope="col">Acesso a conferir</th></tr></thead><tbody>${[['thais-fibula-rotworms','Key 3940 · subsolo −2'],['thais-fibula-beholders','Key 3940 · subsolo −3'],['thais-deeper-fibula-dragons','Porta 50 · teleporte · Key 3980'],['thais-deeper-fibula-dragon-lords','Porta 50 · teleporte · Key 3980']].map(([id,access])=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${h.level}+</td><td>${access}</td></tr>`;}).join('')}</tbody></table></div><p>Rotworms e Beholders pertencem às referências da dungeon; as hunts de dragões exigem o acesso profundo. Estar no mesmo andar não significa estar na mesma sala ou conseguir atravessar de um setor ao outro sem requisitos.</p>`)
 +section('Key 3980 e o ponto sem retorno',`<div class="ab-access-grid">${box('OBTENÇÃO','Use o pequeno buraco','A Key 3980 é coletada usando o pequeno buraco do setor de Minotaur Mages, depois da porta de nível 50 e do teleporte. Não é preciso descer dentro desse buraco. O guia identifica a coleta e a passagem interna que ela abre.',key('3980','Key 3980 · coleta ilustrada'))}${box('RETORNO','Planeje a saída antes de entrar','Se já coletou a Key 3980 em uma visita anterior, leve-a; não presuma uma nova coleta. Reserve cura e recursos para o restante do percurso. A possibilidade de passar pela porta de nível não garante preparo para Dragon Lords.',link('quest','fibula','Consultar percurso completo'))}</div>`)
 +section('Criaturas dos setores subterrâneos',creatures(['Rotworm','Beholder','Minotaur Mage','Dragon','Dragon Lord'])+'<p>Os encontros variam por setor. Minotaur Mages tornam a coleta da chave perigosa; Dragons e Dragon Lords exigem reservas próprias de cura e combate. Os marcadores das hunts apontam respawns de referência, não uma rota segura desde a vila.</p>')
 +section('Checklist antes do poço','<ul class="city-guide-checklist"><li><strong>Chaves:</strong> confira 3940 para a dungeon e 3980 para a passagem profunda.</li><li><strong>Ferramentas:</strong> leve Rope, luz e os recursos de acesso indicados no roteiro; Destroy Field faz parte da preparação registrada da quest.</li><li><strong>Combate:</strong> prepare cura, mana, comida e munição para o objetivo e a saída.</li><li><strong>Porta de nível:</strong> nível 50 libera a passagem registrada; não é recomendação para enfrentar Dragon Lords.</li><li><strong>Capacidade:</strong> confira espaço para as recompensas e preserve as reservas até concluir o retorno.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Preciso fazer Deeper Fibula para caçar Rotworms?</summary><p>Não. São objetivos separados. Abra a hunt de Rotworms e confira o acesso da dungeon com a Key 3940, sem seguir automaticamente para a porta e o teleporte profundos.</p></details><details><summary>A Key 3940 abre toda a área?</summary><p>Ela abre a entrada da Fibula Dungeon. A Key 3980 serve à passagem interna de Deeper Fibula e tem obtenção própria.</p></details><details><summary>Posso voltar pelo teleporte depois de entrar?</summary><p>O guia clássico alerta que a entrada após a porta de nível 50 não permite retornar pelo mesmo teleporte. Leia a rota completa e a saída antes de cruzá-lo.</p></details>');
 }else if(name==='Ancient Temple'){
 body=section('Comece com um destino definido',`<div class="ab-access-grid">${box('01 · CHEGADA','Saia pelo norte de Thais','Procure o acesso ao Ancient Temple ao norte da cidade. O atlas mostra uma referência da região; para chegar a uma hunt, use o mapa da própria ficha. Volte a Thais para reabastecer antes de uma exploração longa.',link('explorador/cities','Thais','Consultar Thais'))}${box('02 · EXPLORAÇÃO','Separe os setores de caça','Os túneis de Rotworms e Orcs são opções diferentes das salas profundas. Não use o nível sugerido de uma hunt como autorização para explorar todas as passagens.',hunt('thais-temple-rotworms')+hunt('thais-temple-orcs'))}${box('03 · PROFUNDIDADE','Mintwallin exige outro preparo','O caminho até a cidade dos minotauros passa por um complexo maior. Confira as hunts de Guards e Mages e as chaves necessárias para o seu objetivo.',link('explorador/cities','Mintwallin','Explorar Mintwallin'))}</div>`)
 +section('Criaturas: confira antes de avançar',creatures(['Poison Spider','Rotworm','Orc','Ghoul','Fire Devil','Minotaur Mage','Dragon'])+'<p>Estas referências abrangem setores e conexões do complexo, com perigos muito diferentes. Não são uma lista de respawn de uma única sala. Veneno, ataques à distância e criaturas fortes tornam arriscado seguir uma passagem sem conhecer o destino.</p>')
 +section('Quests e chaves por objetivo',`<div class="ab-access-grid">${box('GHOUL ROOM','Chave 3600 e sala dos Ghouls','Use o guia da chave para conferir a coleta, o poço e a porta de destino. Ele inclui imagens do caminho e as observações sobre Poison Fields.',key('3600','Abrir caminho ilustrado')+link('quest','ghoul-room','Consultar a quest'))}${box('DEVIL HELMET','Confira requisitos e acesso','A ficha reúne os requisitos da quest. Para o setor do laboratório ligado ao complexo de Mintwallin, consulte também a Key 3610; ela não é a chave da prisão.',link('quest','devil-helmet','Guia de Devil Helmet')+key('3610','Key 3610 · laboratório'))}${box('MINTWALLIN','Prisão e Mad Mage Room','São etapas distintas: a Key 3620 dá acesso à prisão; a obtenção de 3666 envolve A Prisoner e sete Red Apples. Abra o guia antes de organizar essa sequência.',key('3620','Key 3620 · prisão')+key('3666','Key 3666 · Mad Mage')+link('quest','mad-mage-room','Guia da Mad Mage Room'))}</div>`)
 +section('Checklist antes de sair',`<ul class="city-guide-checklist"><li><strong>Rope, Shovel e luz:</strong> confira as ferramentas exigidas pelo guia escolhido.</li><li><strong>Cura e veneno:</strong> reserve recursos para se curar e remover Poison; Destroy Field pode ser necessário nos acessos com campos.</li><li><strong>Retorno:</strong> memorize as mudanças de andar e evite saltos sem verificar como voltar.</li><li><strong>Chaves e equipe:</strong> leve somente os requisitos do seu destino. O guia de uma sala não cobre todas as ramificações.</li></ul>`)
 +section('Dúvidas rápidas','<details><summary>Ancient Temple é uma cidade ou o templo de respawn?</summary><p>É uma região de cavernas associada a Thais. O nome não significa que você encontrará serviços urbanos ou um local de respawn dentro da hunt.</p></details><details><summary>Posso seguir qualquer passagem no nível 15?</summary><p>O nível é uma referência para as hunts de entrada do catálogo. As conexões levam a setores com criaturas e requisitos diferentes; escolha a ficha do destino antes de descer.</p></details><details><summary>Por que Mintwallin tem uma página própria?</summary><p>Ela pertence ao mesmo conjunto de caminhos subterrâneos, mas tem hunts, NPCs e acessos específicos. O resumo do Ancient Temple aponta para essa página sem misturar todos os setores.</p></details>');
 }else if(name==='Arredores de Venore'){
 body=section('Escolha o destino antes de entrar no pântano',`<div class="ab-access-grid">${box('NOROESTE · ACAMPAMENTO','Amazon Camp','Comece pela superfície do acampamento. Torres e subsolos acrescentam perigos: Valkyries e Witches exigem outro preparo. O mapa da hunt indica o setor escolhido.',hunt('amazon-venore'))}${box('SUL E SUDESTE · PRIMEIRAS CAVERNAS','Swamp Trolls e Rotworms','São dois destinos separados: Swamp Trolls na superfície ao sul e Rotworms no primeiro subsolo a sudeste. Abra a ficha certa para não procurar a criatura no andar errado.',hunt('venore-swamp-trolls')+hunt('venore-rotworms'))}${box('SUDESTE · ELVOS','Shadowthorn','O catálogo separa os Elves da superfície, Elf Scouts das torres e Elf Arcanists do subsolo. Mudar de andar também muda a dificuldade.',hunt('venore-shadowthorn-elves')+hunt('venore-shadowthorn-scouts')+hunt('venore-shadowthorn-arcanists'))}${box('SUDOESTE · COVIL','Dragons e Dragon Lords','Escolha o setor de Dragons ou a referência subterrânea de Dragon Lords. A hunt de Dragons não cobre automaticamente os andares mais perigosos.',hunt('dragon-venore')+hunt('venore-dragon-lords'))}</div>`)
 +section('Pântano, villa e regiões vizinhas',`<div class="ab-access-grid">${box('GREEN CLAW SWAMP','Black Knight Villa','A sala do Black Knight faz parte de um complexo com acesso próprio. Confira a Key 5010, o requisito de nível 50 e os perigos antes de seguir para o subsolo.',link('explorador/cities','Green Claw Swamp','Explorar Green Claw Swamp')+link('quest','black-knight','Guia de Black Knight')+key('5010','Key 5010 · acesso à villa'))}${box('PLAINS OF HAVOC','Plains of Havoc tem página própria','Use o resumo de Plains of Havoc para distinguir Giant Spiders, acampamentos e os setores de dragões. São outros destinos, não uma continuação segura das hunts de entrada do pântano.',link('explorador/cities','Plains of Havoc','Explorar Plains of Havoc'))}</div>`)
 +section('Criaturas e sinais de perigo',creatures(['Swamp Troll','Rotworm','Amazon','Valkyrie','Witch','Elf Scout','Elf Arcanist','Dragon','Dragon Lord'])+'<p>As criaturas acima pertencem a destinos diferentes. Não formam um único respawn. Witches e elfos de ataque à distância podem mudar a luta; Dragon Lords exigem preparo distinto de uma caçada de Rotworms.</p>')
 +section('Chaves: saiba qual porta você procura',`<div class="ab-access-grid">${box('KEY 5000','Uma chave, outro objetivo','A Key 5000 possui guia próprio na região de Green Claw Swamp. Leia a obtenção e a descrição da porta: ter uma chave da região não substitui a chave exigida pela villa.',key('5000','Guia ilustrado da Key 5000'))}${box('KEY 5010','Acesso ligado ao Black Knight','Consulte as imagens da coleta e os requisitos. O guia registra a divergência de coordenada na árvore; não apresenta um marcador de coleta como localização exata confirmada.',key('5010','Guia ilustrado da Key 5010'))}</div>`)
 +section('Checklist antes de sair de Venore','<ul class="city-guide-checklist"><li><strong>Destino e andar:</strong> escolha a hunt antes de abrir o mapa. Superfície, torres e subsolo são referências diferentes.</li><li><strong>Suprimentos:</strong> prepare cura, comida, munição e recursos contra veneno para o seu percurso.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e as chaves indicadas no guia de acesso.</li><li><strong>Retorno:</strong> registre as mudanças de andar e a saída que usou. Não desça em passagens desconhecidas para escapar de uma criatura.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>O atlas dos arredores leva diretamente a uma hunt?</summary><p>Este resumo reúne vários destinos e usa os mapas das próprias hunts. Abra a ficha escolhida para ver o setor e o andar específicos. O marcador não é um caminho guiado desde Venore.</p></details><details><summary>Por que Green Claw Swamp e Plains of Havoc têm links separados?</summary><p>São regiões com fichas próprias. Os arredores ajudam a escolher o destino, enquanto cada página reúne suas referências e acessos.</p></details><details><summary>As criaturas e eventos do pântano atual estão incluídos?</summary><p>Este resumo utiliza as referências clássicas do catálogo. Reformas, eventos e criaturas posteriores não foram adicionados como conteúdo do 7.4.</p></details>');
 }else if(name==='Arredores de Kazordoon'){
 body=section('Três áreas, três tipos de exploração',`<div class="ab-access-grid">${box('SUPERFÍCIE · TRAVESSIA','Dwarf Bridge','A ponte fica ao sul da montanha de Kazordoon e conecta caminhos do continente. Dwarfs e Dwarf Soldiers tornam a travessia perigosa para personagens despreparados. Uma rota entre cidades não é uma área protegida.',link('explorador/cities','Kazordoon','Consultar Kazordoon'))}${box('NORTE · COLINAS','Femor Hills','Goblins e Hunter possuem referências em alturas diferentes. A hunt de Goblins está no andar +1; o Hunter do catálogo fica no +3. Confira as escadas e não trate todas as colinas como uma única hunt.',hunt('kazordoon-femor-goblins')+hunt('kazordoon-femor-hunter'))}${box('OESTE · SUBSOLO','Minas externas','O conjunto das minas reúne setores de dificuldade crescente. Escolha a ficha da criatura e o andar pretendido antes de descer. A presença de Dwarfs nos primeiros setores não descreve os andares profundos.',hunt('dwarf-mines')+hunt('kazordoon-dwarf-soldiers'))}${box('SUPERFÍCIE · DRAGON','Um respawn específico','O Dragon da superfície tem ficha própria na região leste da montanha. Consulte seu ponto de referência; ele não é uma rota para as minas ou para Femor Hills.',hunt('kazordoon-dragon-surface'))}</div>`)
 +section('Minas: escolha o setor pelo preparo',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Hunts do catálogo · níveis de referência, sem garantia de segurança</caption><thead><tr><th scope="col">Setor</th><th scope="col">Nível</th><th scope="col">Guia</th></tr></thead><tbody>${['kazordoon-rotworms','dwarf-mines','kazordoon-dwarf-soldiers','dwarf-guards','kazordoon-slimes','kazordoon-dwarf-geomancers'].map(id=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return h?`<tr><th scope="row">${esc(h.name)}</th><td>${h.level}+</td><td>${link('hunt',h.id,'Abrir setor')}</td></tr>`:'';}).join('')}</tbody></table></div><p>Dwarf Guards e Dwarf Geomancers não são uma extensão equivalente aos primeiros Dwarfs. Confira ataques, cura e recursos de combate na ficha antes de avançar.</p>`)
 +section('Quests e acessos com requisitos próprios',`<div class="ab-access-grid">${box('PARADOX TOWER','Planeje a quest inteira','A torre tem guia próprio com requisitos e etapas. A Key 3899 está relacionada ao seu acesso: consulte como obtê-la antes de viajar. Chegar à região não equivale a completar os enigmas.',link('quest','the-paradox-tower','Guia de The Paradox Tower')+key('3899','Key 3899 · obtenção e uso'))}${box('OUTRO DESTINO · DENTRO DE KAZORDOON','Dwacatra não é uma mina externa','A prisão fica no subsolo de Kazordoon e exige acesso próprio. A Key 3802 está ligada à Emperor’s Cookies Quest; abra a sequência antes de procurar a prisão.',link('quest','emperor-s-cookies','Emperor’s Cookies · guia')+key('3802','Key 3802 · acesso a Dwacatra')+hunt('kazordoon-dwacatra'))}</div>`)
 +section('Criaturas: superfície e subsolo',creatures(['Dwarf','Dwarf Soldier','Dwarf Guard','Dwarf Geomancer','Rotworm','Slime','Goblin','Hunter','Dragon'])+'<p>Estes destinos têm grupos de criaturas distintos. Hunter ataca à distância; os setores de Guards e Geomancers exigem mais preparo que as áreas iniciais. Consulte a ficha da hunt em vez de usar um nível único para toda a região.</p>')
 +section('Checklist antes de explorar','<ul class="city-guide-checklist"><li><strong>Ferramentas e luz:</strong> confira Rope e Shovel conforme a entrada escolhida; leve iluminação para o subsolo.</li><li><strong>Andar:</strong> observe a diferença entre as colinas elevadas, a superfície e os níveis das minas.</li><li><strong>Suprimentos:</strong> prepare cura, comida, munição e capacidade para trazer o loot sem comprometer o retorno.</li><li><strong>Acessos:</strong> Paradox Tower e Dwacatra têm requisitos próprios. Confira o guia antes de separar chaves.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Arredores é a mesma coisa que a cidade subterrânea?</summary><p>Não. Este resumo reúne travessias, colinas e minas externas. Os serviços urbanos e a prisão de Dwacatra ficam ligados à página de Kazordoon.</p></details><details><summary>Posso descer seguindo qualquer escada nas minas?</summary><p>As minas têm setores e andares com perigos diferentes. Abra a hunt escolhida, confira o andar e preserve o caminho de volta antes de avançar.</p></details><details><summary>O mapa é uma rota completa desde o depot?</summary><p>Não. Os marcadores identificam referências do catálogo. As fichas distinguem o respawn, os requisitos e o andar; não confirmam cada passo de uma rota desde a cidade.</p></details>');
 }else if(name==="Ashta'daramai"){
 body=section('Entenda o acesso antes de viajar',`<div class="ab-access-grid">${box('01 · LOCALIZAÇÃO','Fortaleza dos Blue Djinns','Ashta’daramai fica em Kha’zeel, na região de Darama. É uma fortaleza com vários andares, não uma cidade com todos os serviços. O atlas abre uma referência do local, sem calcular a rota desde Ankrahmun.',link('explorador/cities','Ankrahmun','Preparar a viagem em Ankrahmun'))}${box('02 · FACÇÃO','Marid: o caminho dos djinns azuis','O guia de The Djinn War — Marid Faction descreve a preparação, as conversas e as missões. Conhecer a saudação e entrar na fortaleza não significa que o comércio já esteja liberado.',link('quest','the-djinn-war-marid-faction','Começar pelo guia Marid'))}${box('03 · COMÉRCIO','Conclua a autorização necessária','Nah’Bob e Haroun são comerciantes ligados ao caminho Marid. Antes de transportar equipamentos pesados, confira no guia se o seu personagem concluiu a etapa que permite negociar.',link('npc',"Nah'Bob",'Ficha de Nah’Bob')+link('npc','Haroun','Ficha de Haroun'))}${box('OUTRA FACÇÃO','Não confunda com Mal’ouquah','Alesar e Yaman pertencem ao caminho Efreet, associado à outra fortaleza. Leia as diferenças antes de escolher a facção; o acesso Marid não equivale à liberação dos dois lados.',link('quest','the-djinn-war-efreet-faction','Comparar com o guia Efreet'))}</div>`)
 +section('Quem compra o seu loot?',`<div class="ab-service-grid">${npc("Nah'Bob",'Armas, armaduras e escudos')}${npc('Haroun','Itens mágicos e anéis')}</div><p>As fichas separam <strong>o NPC compra de você</strong> de <strong>o NPC vende para você</strong>. Confira o item e o preço na lista certa. A existência de uma oferta no catálogo não confirma que seu personagem já tenha autorização para usá-la.</p>`)
 +section('NPCs da fortaleza: encontre a ficha certa',`<div class="ab-service-grid">${npc('Umar','Entrada e primeiro contato')}${npc("Bo'Ques",'Referência nas missões Marid')}${npc("Fa'Hradin",'Referência nas missões Marid')}${npc('Gabel','Liderança dos Blue Djinns')}</div><p>Use o guia Marid para seguir a ordem das conversas. As fichas dos NPCs ajudam a consultar o andar e a localização; não substituem os pré-requisitos da quest.</p>`)
 +section('Checklist antes de iniciar The Djinn War','<ol class="city-guide-checklist"><li><strong>Escolha o lado:</strong> leia o guia Marid e compare com Efreet antes de iniciar as missões.</li><li><strong>Confira os requisitos:</strong> prepare o que o guia pede, incluindo as conversas iniciais e os itens das etapas.</li><li><strong>Planeje os deslocamentos:</strong> as missões envolvem locais fora da fortaleza. Entrar em Ashta’daramai não encerra a quest.</li><li><strong>Confirme o comércio:</strong> conclua a autorização antes de planejar uma viagem carregada de loot.</li></ol>')
 +section('Combate e deslocamento',creatures(['Blue Djinn','Marid'])+'<p>As criaturas são referências do complexo dos djinns azuis, não uma indicação de que você deve atacá-las para negociar. A relação com a facção e o objetivo da visita mudam a preparação. Consulte o guia da sua missão antes de entrar por passagens ou avançar andares.</p>')
 +section('Dúvidas rápidas','<details><summary>Posso vender assim que chegar à fortaleza?</summary><p>O comércio clássico está ligado à conclusão do caminho Marid. O primeiro contato e a entrada são etapas diferentes da autorização para negociar.</p></details><details><summary>Qual é a diferença entre Nah’Bob e Haroun?</summary><p>As listas de comércio são diferentes. Abra as fichas para procurar o equipamento e conferir se o NPC compra ou vende aquele item.</p></details><details><summary>Preciso de uma chave numerada?</summary><p>Não há uma chave numerada associada a esta região no catálogo. O acesso descrito usa os requisitos e as conversas de The Djinn War; não foi criada uma dependência de chave sem fonte.</p></details><details><summary>O mapa mostra o NPC em tempo real?</summary><p>Não. A ficha usa uma referência clássica e informa o andar. O NPC pode caminhar perto do ponto; no Mythera, essas posições ainda precisam de validação em campo.</p></details>');
 }else if(name==='Carlin'){
 body=section('Resolva o essencial antes de sair',`<div class="ab-service-grid">${npc('Cornelia','Armaduras e equipamentos')}${npc('Rowenna','Armas e comércio de equipamentos')}${npc('Rachel','Itens mágicos e suprimentos')}${npc('Captain Greyhound','Viagens pelo porto')}${npc('Nielson','Balsa para as ilhas de gelo')}${npc('Legola','Referência de magias para Paladins')}</div><p>Abra a ficha para consultar ofertas e referências de localização. Professores clássicos e vendedores têm funções diferentes; uma magia ensinada não é uma runa pronta à venda.</p>`)
 +section('Escolha uma hunt próxima',`<div class="ab-access-grid">${box('CAVERNAS','Rotworms na região de Carlin','A referência do catálogo está no subsolo -2. Consulte o mapa da hunt e prepare a volta: o marcador mostra um respawn, não um caminho completo desde o depot.',hunt('rotworm-carlin'))}${box('LESTE · ACAMPAMENTO','Amazons de Carlin','Este é o pequeno acampamento de Carlin. Ele tem ficha própria e não é o Amazon Camp de Venore. Confira o destino antes de seguir um guia ou abrir o mapa.',hunt('carlin-amazon'))}${box('LESTE · CEMITÉRIO','Cripta e cavernas dos Trolls','Confira a Key 3520 antes de procurar o acesso. O mapa da hunt abre no setor subterrâneo dos Trolls e não na porta da cripta.',hunt('carlin-graveyard')+key('3520','Key 3520 · obtenção e porta'))}${box('OESTE · GHOSTLANDS','Escolha o setor antes de descer','Skeletons, Ghouls, Demon Skeletons e Vampire ficam em referências distintas. A dificuldade dos primeiros setores não descreve todos os andares profundos.',link('explorador/cities','Ghostlands','Explorar Ghostlands')+hunt('carlin-ghostlands-skeletons')+hunt('carlin-ghostlands-ghouls'))}</div>`)
 +section('Ilhas: transporte e acesso são diferentes',`<div class="ab-access-grid">${box('BALSA DE NIELSON','Folda, Senja e Vega','A balsa das ilhas de gelo tem referência própria ao noroeste de Carlin. Escolha a ilha e confira o caminho de volta antes de explorar os subsolos.',link('explorador/cities','Folda','Explorar Folda')+link('explorador/cities','Senja','Explorar Senja')+link('explorador/cities','Vega','Explorar Vega')+link('npc','Nielson','Localizar Nielson'))}${box('ACESSO POR QUEST','Isle of the Kings','A viagem com Dalbrect depende da etapa de acesso de The White Raven Monastery, com entrega do Family Brooch. As portas das catacumbas envolvem a investigação com Costello.',link('explorador/cities','Isle of the Kings','Explorar Isle of the Kings')+link('quest','the-white-raven-monastery','Conferir acesso ao mosteiro')+key('3350','Key 3350 · uso e obtenção'))}</div>`)
 +section('Quests e chaves: prepare o objetivo',`<div class="ab-access-grid">${box('ILHAS DE GELO','Alawar’s Vault','O guia reúne a sequência da quest e suas referências. As Keys 4501, 4502 e 4503 possuem guias próprios; confira a função de cada uma em vez de tratar as três como equivalentes.',link('quest','alawar-s-vault','Guia de Alawar’s Vault')+key('4501','Key 4501')+key('4502','Key 4502')+key('4503','Key 4503'))}${box('GHOSTLANDS','The Queen of the Banshees','É uma expedição com requisitos e desafios próprios, muito diferente de caçar nos primeiros setores de Ghostlands. Leia o guia completo antes de organizar a equipe.',link('quest','the-queen-of-the-banshees','Consultar guia de Banshee'))}</div>`)
 +section('Criaturas: a região muda com o destino',creatures(['Rotworm','Amazon','Troll','Skeleton','Ghoul','Demon Skeleton','Vampire','Frost Troll'])+'<p>Estas criaturas pertencem a áreas distintas de Carlin e das regiões relacionadas. Não são uma lista de respawn de uma única caverna. Escolha a hunt para consultar seu setor, nível de referência e perigos.</p>')
 +section('Checklist antes da viagem','<ul class="city-guide-checklist"><li><strong>Destino:</strong> diferencie a hunt próxima da cidade das viagens para ilhas e Ghostlands.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e luz para os subsolos indicados pelo guia.</li><li><strong>Chaves:</strong> a Key 3520 atende à cripta; as chaves das ilhas têm outros usos. Consulte a porta de destino.</li><li><strong>Acesso e retorno:</strong> prepare a etapa do mosteiro para Isle of the Kings e a referência da balsa para as ilhas de gelo.</li><li><strong>Suprimentos:</strong> compre cura, comida e munição antes de embarcar; o resumo da cidade não garante esses serviços em cada ilha.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>Carlin Amazon Camp é a mesma quest filmada em Venore?</summary><p>Não são o mesmo local. O acampamento de Carlin tem uma hunt separada; use o guia de Venore para o material registrado naquele acampamento.</p></details><details><summary>Por que o filtro da cidade pode incluir as ilhas?</summary><p>A opção de incluir regiões relacionadas reúne os locais vinculados a Carlin. Desative-a para consultar somente as referências da cidade.</p></details><details><summary>A Key 3520 confirma toda a Fanfare Quest no 7.4?</summary><p>Não. A chave tem sua própria ficha de acesso, enquanto a quest Fanfare permanece com presença histórica em revisão no catálogo. O acesso à cripta não comprova automaticamente a recompensa da quest.</p></details>');
 }else if(name==='Cormaya'){
 body=section('Escolha o transporte pelo destino',`<div class="ab-access-grid">${box('CAIS · PEMARET','Edron e a visita a Eremo','Pemaret é a referência de transporte da ilha para Edron e para a visita ao sábio Eremo. Confira o NPC e seu andar antes de procurar o barco: não é o mesmo embarque do steamship subterrâneo.',link('npc','Pemaret','Localizar Pemaret')+link('explorador/cities','Edron','Consultar Edron'))}${box('SUBSOLO · GURBASCH','Barco a vapor para Kazordoon','O steamship é um acesso subterrâneo e utiliza outro NPC. Consulte a referência de Gurbasch antes de descer. Este resumo clássico não acrescenta destinos de expansões posteriores.',link('npc','Gurbasch','Localizar Gurbasch')+link('explorador/cities','Kazordoon','Consultar Kazordoon'))}${box('OUTRA ILHA · EREMO','Consulte o serviço antes de viajar','Eremo fica em sua própria ilha. A visita parte da referência de Pemaret, mas o serviço é consultado na ficha de Eremo: não procure o sábio nas ruas de Cormaya.',link('npc','Eremo','Serviços de Eremo'))}${box('MORADIA · YOEM','Móveis para a casa','Yoem tem uma ficha de comércio própria. Abra a lista para verificar os móveis, preços e a posição de referência antes de organizar uma compra.',link('npc','Yoem','Consultar móveis de Yoem'))}</div>`)
 +section('NPCs com função definida',`<div class="ab-service-grid">${npc('Pemaret','Transporte da ilha')}${npc('Gurbasch','Steamship no subsolo')}${npc('Yoem','Móveis e decoração')}${npc('Eremo','Serviços na ilha de Eremo')}</div><p>Eremo é apresentado como destino relacionado, não como morador de Cormaya. A ficha permanece ligada à mesma referência de NPC da biblioteca.</p>`)
 +section('Checklist para organizar a visita','<ol class="city-guide-checklist"><li><strong>Defina o destino:</strong> Edron, Eremo e Kazordoon envolvem referências de embarque diferentes.</li><li><strong>Confira o andar:</strong> o barco de Pemaret e o steamship de Gurbasch não estão no mesmo piso.</li><li><strong>Prepare os custos:</strong> consulte a referência do serviço e leve recursos antes de sair. Não é apresentado um preço ao vivo.</li><li><strong>Planeje a volta:</strong> registre o caminho entre o cais, os acessos subterrâneos e o ponto de retorno.</li></ol>')
 +section('Eremo: o que conferir na ficha',`<div class="ab-access-grid">${box('SERVIÇOS CLÁSSICOS','Amulet of Loss e magias registradas','A ficha de Eremo contém o Amulet of Loss e referências de magias. Confira preço, vocação e os requisitos aplicáveis antes da viagem; visualizar o serviço não confirma que o personagem pode comprá-lo.',link('npc','Eremo','Abrir ficha de Eremo'))}${box('PREPARAÇÃO','Reabasteça antes da exploração','Para equipamentos e outros serviços urbanos, consulte a biblioteca de Edron. Não atribuímos automaticamente a Cormaya os comerciantes que ficam na cidade vizinha.',link('explorador/cities','Edron','Serviços e referências de Edron'))}</div>`)
 +section('Hunts, quests e chaves: o que está documentado','<aside class="city-guide-notice"><strong>O catálogo ainda não possui uma hunt própria de Cormaya.</strong><p>Não foi criada uma rota de caverna sem referência revisada. Também não há quest ou chave numerada associada a esta região no catálogo atual. O resumo reúne os transportes e serviços identificados; novas cavernas precisam de revisão de criaturas, andar e acesso antes de virar guia.</p></aside>')
 +section('Dúvidas rápidas','<details><summary>Cormaya é a mesma cidade que Edron?</summary><p>É uma ilha relacionada a Edron, com referências de transporte e NPCs próprios. Os serviços de Edron não ficam automaticamente disponíveis na ilha.</p></details><details><summary>Por que o marcador de Gurbasch fica muito abaixo da superfície?</summary><p>O steamship utiliza um acesso subterrâneo. O marcador identifica a referência do NPC, não um trajeto desenhado do cais até ele.</p></details><details><summary>Posso usar uma rota moderna para Farmine ou outro destino?</summary><p>Este resumo considera o recorte 7.4. Destinos de versões posteriores não foram incorporados à lista clássica de transportes.</p></details>');
 }else if(name==='Darashia'){
 body=section('Prepare os serviços na cidade',`<div class="ab-service-grid">${npc('Azil','Armaduras e equipamentos')}${npc('Habdel','Armas e comércio de loot')}${npc('Halif','Mochilas, ferramentas e luz')}${npc('Miraia','Comida e bebidas')}${npc('Edoch','Arcos e bestas')}${npc('Chemar','Viagem de tapete mágico')}</div><p>Confira os itens na ficha: o que o NPC compra de você é separado do que vende. A referência clássica de comércio não informa estoque ou acesso em tempo real no servidor.</p>`)
 +section('Magias, templo e serviços relacionados',`<div class="ab-service-grid">${npc('Shalmar','Referência clássica de magias')}${npc('Kasmir','Referência do templo')}${npc('Ishina','Amuletos do catálogo')}${npc('Hofech','Móveis para moradia')}</div><p>O resumo mantém as referências da base clássica. Não foram adicionados os serviços de Asima, introduzida depois do 7.4, nem operações bancárias modernas como regra histórica.</p>`)
 +section('Primeiro escolha a área de caça',`<div class="ab-access-grid">${box('OESTE · CAVERNAS','Rotworms de Darashia','Use a ficha da caverna antes de descer. O ponto do mapa indica um respawn de referência; ele não é uma entrada de caverna nem uma rota completa desde o depot.',hunt('darashia-rotworms'))}${box('NORDESTE · PIRÂMIDE','Minotaurs na superfície','O guia dos Minotaurs usa o térreo e a área externa da pirâmide. Não procure esse marcador no subsolo e não use seu nível de referência para os setores profundos.',hunt('minotaur-darashia'))}${box('PIRÂMIDE · SUBSOLO','Guards e Mages são outros setores','Minotaur Guards têm referência no primeiro subsolo; Minotaur Mages ficam em um setor mais profundo. Abra a ficha correspondente para consultar os perigos antes de mudar de andar.',hunt('darashia-minotaur-guards')+hunt('darashia-minotaur-mages'))}${box('OESTE · RUÍNAS','Drefia tem resumo próprio','O conjunto das ruínas reúne setores diferentes de mortos-vivos. Comece pelo resumo de Drefia e escolha a hunt; chegar às ruínas não significa estar no respawn de Necromancers.',link('explorador/cities','Drefia','Explorar Drefia'))}</div>`)
 +section('Drefia: destinos por criatura',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Referências clássicas de Drefia · cada hunt possui seu próprio setor</caption><thead><tr><th scope="col">Hunt</th><th scope="col">Nível de referência</th><th scope="col">Guia</th></tr></thead><tbody>${['drefia-ghouls','drefia-beholders','drefia-demon-skeletons','drefia-vampires','necromancer-drefia'].map(id=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return h?`<tr><th scope="row">${esc(h.name)}</th><td>${h.level}+</td><td>${link('hunt',h.id,'Abrir setor')}</td></tr>`:'';}).join('')}</tbody></table></div><p>Os níveis são sugestões do catálogo, não garantia de segurança. As posições de respawn não substituem o acesso à caverna ou uma rota de retorno.</p>`)
 +section('Quests documentadas da região',`<div class="ab-access-grid">${box('MEDUSA SHIELD','Prepare o acesso de Drefia','O guia reúne os requisitos, ferramentas e referências da quest. Leia a preparação antes de entrar nas ruínas; não confunda o destino da recompensa com um marcador genérico de hunt.',link('quest','medusa-shield','Guia de Medusa Shield'))}${box('OUTRAS RECOMPENSAS','Plate Armor e Stealth Ring','São fichas distintas do catálogo. Confira os requisitos e a localização descritos em cada guia antes de seguir para o destino.',link('quest','plate-armor','Guia de Plate Armor')+link('quest','stealth-ring','Guia de Stealth Ring'))}</div>`)
 +section('Criaturas: cidade, pirâmide e ruínas',creatures(['Rotworm','Minotaur','Minotaur Guard','Minotaur Mage','Ghoul','Beholder','Demon Skeleton','Vampire','Necromancer'])+'<p>A lista reúne destinos diferentes. A pirâmide dos minotauros não é Drefia; os mortos-vivos das ruínas não são uma lista de criaturas presentes em toda caverna próxima da cidade.</p>')
 +section('Checklist antes de sair','<ul class="city-guide-checklist"><li><strong>Objetivo:</strong> escolha uma hunt ou quest específica e confira a região de destino.</li><li><strong>Andar:</strong> separe a superfície da pirâmide dos setores de Guards e Mages.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel, luz e as exigências do guia. Algumas etapas de quest têm preparação adicional.</li><li><strong>Cura e combate:</strong> prepare comida, cura, mana e munição conforme as criaturas do setor.</li><li><strong>Retorno:</strong> observe as mudanças de andar e preserve o caminho de volta. Nenhum marcador deste resumo calcula uma rota completa.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>O atlas de Darashia abre a pirâmide ou Drefia?</summary><p>O botão da cidade mostra uma visão geral. Abra a hunt ou quest escolhida para consultar seu próprio setor e andar.</p></details><details><summary>Preciso de uma chave numerada para todas essas hunts?</summary><p>O catálogo não associa uma chave numerada à cidade de Darashia. Confira os requisitos do destino; não foi criada uma exigência de chave sem referência.</p></details><details><summary>A reforma moderna de Drefia está incluída?</summary><p>Este resumo usa os setores clássicos já revisados no catálogo. Áreas e missões posteriores não foram incorporadas como conteúdo do 7.4.</p></details>');
 }else if(name==='Draconia'){
 body=section('Prepare a travessia inteira',`<div class="ab-access-grid">${box('01 · AB’DENDRIEL','Entrada por Hellgate','A Key 3012 está ligada à entrada de Hellgate. Leia o guia de obtenção antes de sair; essa chave não é uma das oito chaves da pirâmide de Draconia.',key('3012','Key 3012 · entrada de Hellgate')+link('explorador/cities',"Ab'Dendriel",'Preparar em Ab’Dendriel'))}${box('02 · CAMINHO SUBTERRÂNEO','Hellgate e Red Bone Castle','A travessia clássica passa por Hellgate e Red Bone Castle antes de chegar à ilha. Consulte o guia de Draconia para separar as etapas. O marcador da ilha não é um acesso direto desde a superfície de Ab’Dendriel.',link('quest','draconia','Guia completo da expedição')+link('explorador/cities','Hellgate','Explorar Hellgate'))}${box('03 · PIRÂMIDE','Chaves e mecanismos','As Keys 3001 a 3008 estão ligadas à progressão da pirâmide. Consulte a obtenção e o uso de cada chave. O roteiro possui mecanismos com participação de dois personagens: organize a equipe antes da viagem.',key('3001','Começar pela Key 3001')+link('quest','draconia','Conferir requisitos e mecanismos'))}${box('04 · RETORNO','Não deixe a saída para depois','O guia da quest inclui o portal de saída e as alavancas relacionadas. Confira essa etapa antes de atravessar Hellgate; a Key 3012 não substitui o mecanismo de retorno.',link('quest','draconia','Consultar o retorno no guia'))}</div>`)
 +section('Chaves da pirâmide: obtenção e uso',`<p>As descrições abaixo vêm das fichas clássicas já revisadas. Cada guia traz as imagens e as observações da etapa; a numeração não substitui os mecanismos descritos no roteiro.</p><div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Keys 3001–3008 · referências da quest Draconia</caption><thead><tr><th scope="col">Chave</th><th scope="col">Onde obter</th><th scope="col">Uso</th></tr></thead><tbody>${Array.from({length:8},(_,i)=>String(3001+i)).map(id=>{const k=window.CLASSIC_RESOURCES.keys.find(k=>k.number===id);return `<tr><th scope="row">${key(id,'Key '+id)}</th><td>${esc(k.obtain)}</td><td>${esc(k.use)}</td></tr>`;}).join('')}</tbody></table></div>`)
 +section('Hunts: três setores diferentes',`<div class="ab-access-grid">${box('PIRÂMIDE · ANDAR +3','Demon Skeletons','A referência de caça fica em um andar elevado da pirâmide. Confira as chaves e os requisitos do caminho antes de procurar o respawn.',hunt('abdendriel-draconia-demon-skeletons'))}${box('CAVERNA · SUBSOLO -2','Dragon','O Dragon da caverna tem referência subterrânea própria. Ele não é o Dragon Lord da torre e não fica no andar dos Demon Skeletons.',hunt('abdendriel-draconia-dragons'))}${box('TORRE · ANDAR +4','Dragon Lord','A torre ao norte da ilha tem um setor mais perigoso. Consulte a ficha e prepare recursos para a viagem completa, incluindo a saída.',hunt('abdendriel-draconia-dragon-lord'))}</div>`)
 +section('Criaturas da expedição',creatures(['Demon Skeleton','Dragon','Dragon Lord'])+'<p>As imagens identificam as criaturas das hunts de Draconia do catálogo. Elas ficam em setores distintos; não representam todos os encontros possíveis durante a travessia de Hellgate.</p>')
 +section('Checklist da viagem','<ul class="city-guide-checklist"><li><strong>Acesso:</strong> confira a Key 3012 e o caminho de Hellgate no guia.</li><li><strong>Chaves:</strong> verifique quais das Keys 3001–3008 você já possui e quais pretende obter na expedição.</li><li><strong>Equipe:</strong> prepare dois personagens para os mecanismos que exigem participação conjunta.</li><li><strong>Ferramentas e combate:</strong> leve Rope, luz, cura e Destroy Field conforme os requisitos do roteiro.</li><li><strong>Saída:</strong> leia a etapa das alavancas e do portal de retorno antes de iniciar a travessia.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>A Key 3012 abre as portas da pirâmide?</summary><p>Ela está ligada ao acesso de Hellgate. As portas e mecanismos de Draconia usam as referências das Keys 3001 a 3008 e o roteiro da quest.</p></details><details><summary>O mapa da ilha mostra o caminho desde Ab’Dendriel?</summary><p>Não. O atlas abre a referência de Draconia. O guia da quest separa a entrada, a travessia e as etapas da pirâmide.</p></details><details><summary>Posso preparar a saída só depois de terminar?</summary><p>Consulte o mecanismo de retorno antes de ir. A viagem envolve acessos e recursos próprios; chegar à recompensa não garante que você já tenha organizado a volta.</p></details>');
 }else if(name==='Drefia'){
 body=section('Oriente-se antes de entrar nas ruínas',`<div class="ab-access-grid">${box('CIDADE DE APOIO','Reabasteça em Darashia','Drefia fica a oeste de Darashia. Organize cura, comida, mana e munição na cidade antes de seguir para as ruínas. Os comerciantes de Darashia não são apresentados como serviços dentro da dungeon.',link('explorador/cities','Darashia','Serviços e preparação em Darashia'))}${box('ENTRADA E RESPAWN','O marcador da hunt é outro ponto','O atlas da região mostra uma visão geral. As hunts abrem referências de respawn em seus próprios andares, sem desenhar um percurso completo desde a cidade. Escolha primeiro o setor que deseja visitar.',hunt('drefia-ghouls'))}${box('OBJETIVO DE CAÇA','Escolha criatura e profundidade','Ghouls, Beholders, Demon Skeletons, Vampires e Necromancers têm fichas diferentes. Não use o nível de uma hunt mais simples como indicação para explorar todas as passagens.',hunt('drefia-beholders')+hunt('drefia-demon-skeletons'))}${box('OBJETIVO DE QUEST','Medusa Shield tem requisitos próprios','O guia possui acesso e porta de nível 60 registrados. Leia ferramentas e preparação antes de sair; o mapa de uma hunt de Drefia não substitui as etapas dessa quest.',link('quest','medusa-shield','Consultar Medusa Shield'))}</div>`)
 +section('Setores de caça do catálogo',`<div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Drefia clássica · níveis de referência, sem garantia de segurança</caption><thead><tr><th scope="col">Setor</th><th scope="col">Nível</th><th scope="col">Referência</th></tr></thead><tbody>${['drefia-ghouls','drefia-beholders','drefia-demon-skeletons','drefia-vampires','necromancer-drefia'].map(id=>{const h=window.CLASSIC_HUNTS.find(h=>h.id===id);return `<tr><th scope="row">${link('hunt',id,h.name)}</th><td>${h.level}+</td><td>${esc(h.access)}</td></tr>`;}).join('')}</tbody></table></div>`)
 +section('Reconheça as criaturas',creatures(['Ghoul','Beholder','Demon Skeleton','Vampire','Necromancer'])+'<p>As criaturas pertencem aos setores clássicos listados acima. Consulte os ataques e perigos na ficha da hunt e no bestiário antes de escolher o equipamento. A presença de uma criatura na região não confirma um respawn em cada andar.</p>')
 +section('Quest documentada: Medusa Shield',`<div class="ab-access-grid">${box('PREPARAÇÃO','Leia o acesso antes de descer','O roteiro registra o acesso pelas ruínas, o preparo com Rope e os recursos de subida indicados no guia. Confira a porta de nível e os requisitos da recompensa antes de organizar a expedição.',link('quest','medusa-shield','Abrir guia de Medusa Shield'))}${box('NÃO MISTURE OS DESTINOS','Outras quests de Darashia','Stealth Ring está ligada à pirâmide dos minotauros. Plate Armor tem uma referência de acesso pelo Ghost Ship. Essas quests não foram colocadas no filtro de Drefia.',link('explorador/cities','Darashia','Ver os outros destinos de Darashia'))}</div>`)
 +section('Checklist antes de explorar','<ul class="city-guide-checklist"><li><strong>Escolha:</strong> defina se vai caçar em um setor específico ou seguir a quest.</li><li><strong>Ferramentas:</strong> confira Rope, luz e as exigências de subida ou descida do roteiro escolhido.</li><li><strong>Suprimentos:</strong> prepare cura, comida, mana e recursos de combate para mortos-vivos.</li><li><strong>Retorno:</strong> observe cada mudança de andar e não confunda um marcador de respawn com a entrada da caverna.</li><li><strong>Requisitos:</strong> para Medusa Shield, confira a porta de nível 60 e os demais preparos no guia.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>As áreas modernas de Drefia estão incluídas?</summary><p>Este resumo usa as cinco hunts clássicas revisadas do catálogo. Reformas, novas criaturas e missões posteriores não foram incorporadas como conteúdo do 7.4.</p></details><details><summary>Preciso de uma chave numerada para entrar?</summary><p>O catálogo não associa uma chave numerada a Drefia. Verifique ferramentas e requisitos do destino escolhido; não foi acrescentada uma chave sem referência.</p></details><details><summary>Posso usar o mapa dos Necromancers para achar a entrada?</summary><p>O marcador dos Necromancers indica um respawn no andar 10, não a entrada da dungeon. Use o roteiro do destino para conferir o acesso.</p></details>');
 }else if(name==='Edron'){
 body=section('Serviços para preparar a expedição',`<div class="ab-service-grid">${npc('Willard','Equipamentos e comércio de loot')}${npc('Sandra','Fluidos de cura e mana')}${npc('Beatrice','Mochilas e suprimentos')}${npc('Alexander','Runas em branco e itens mágicos')}${npc('Bonifacius','Alimentos do catálogo')}${npc('Captain Seahorse','Transporte por barco')}</div><p>Confira ofertas, preços e o andar na ficha do NPC. Compra de item, ensino de magia e viagem são serviços diferentes; o resumo não informa acesso ou estoque ao vivo.</p>`)
 +section('Comece pelo destino, não por uma dificuldade única',`<div class="ab-access-grid">${box('CAVERNAS PRÓXIMAS','Trolls, Goblins e Rotworms','Os Trolls e Goblins têm referências na península a oeste; os Rotworms ficam na região ao sul da cidade. Abra a hunt escolhida para conferir o setor e o andar.',hunt('edron-trolls')+hunt('edron-goblins')+hunt('edron-rotworms'))}${box('SUDOESTE · PENÍNSULA','Orcs e passagem de retorno','O acesso clássico passa pelo porão dos apartamentos ao sul do castelo. A ficha orienta levar Shovel para reabrir a passagem de volta. O marcador de Orcs fica na superfície, não no túnel de entrada.',hunt('edron-orcs'))}${box('NORTE · CYCLOPOLIS','Cyclops e Behemoths','Os Cyclops usam uma referência no primeiro subsolo. Os Behemoths ficam em um setor profundo no andar 14. Uma hunt de Cyclops não descreve a dificuldade de todo o complexo.',hunt('edron-cyclopolis')+hunt('edron-behemoths'))}${box('NOROESTE · COVIL','Dragons e Dragon Lords','As duas fichas distinguem os setores do covil. Confira recursos de combate e cura antes de avançar dos Dragons para o setor profundo de Dragon Lords.',hunt('edron-dragons')+hunt('edron-dragon-lords'))}</div>`)
 +section('Outros destinos do norte',`<div class="ab-access-grid">${box('HERO CAVE','Heroes nos corredores profundos','A referência da hunt fica nos corredores de Heroes. O ponto de respawn não indica uma entrada completa desde a cidade; leia a preparação antes de ir.',hunt('hero-edron'))}${box('GHOUL HILL','A referência é no alto da colina','A ficha aponta o setor superior, no andar +3, com Ghouls e referência de Demon Skeleton. Ela não representa os andares iniciais de Ghoul Hill.',hunt('edron-ghoul-hill'))}</div>`)
 +section('Quests: separe as expedições avançadas',`<div class="ab-access-grid">${box('ANNIHILATOR','Prepare o grupo e os requisitos','Abra o guia para conferir o nível exigido, a equipe e o mecanismo de entrada. O desafio não é equivalente a uma caçada comum de Heroes.',link('quest','annihilator','Guia de Annihilator'))}${box('DEMON HELMET','Chave e requisitos próprios','O guia da quest e a Key 6010 possuem referências complementares. Confira a obtenção da chave, a porta e a preparação antes de seguir ao setor de Demons.',link('quest','demon-helmet','Guia de Demon Helmet')+key('6010','Key 6010 · obtenção e uso'))}${box('DESTINOS DISTINTOS','Behemoth e Fire Axe','Behemoth está ligada aos andares profundos de Cyclopolis; Fire Axe possui referência no Dragon Lair. Abra o guia da recompensa escolhida para conferir as ferramentas e o acesso.',link('quest','behemoth','Guia de Behemoth')+link('quest','fire-axe','Guia de Fire Axe'))}${box('OUTRAS REFERÊNCIAS','Escolha a recompensa pelo guia','Edron Goblin, Troll Cave e Vampire Shield são fichas separadas e têm preparações diferentes. Vampire Shield possui referência na Hero Cave; consulte os perigos do guia antes de organizar a viagem.',link('quest','edron-goblin','Guia de Edron Goblin')+link('quest','troll-cave','Guia de Troll Cave')+link('quest','vampire-shield','Guia de Vampire Shield'))}</div>`)
 +section('Transportes e locais relacionados',`<div class="ab-service-grid">${npc('Captain Seahorse','Barco e viagens da cidade')}${npc('Pino','Referência de tapete mágico')}</div><div class="city-guide-links">${link('explorador/cities','Cormaya','Cormaya · transportes e serviços')}${link('explorador/cities',"Eremo's Island",'Ilha de Eremo · referência')}${link('explorador/cities','Stonehome','Stonehome · referência')}</div><p>A visita a Eremo está ligada ao transporte de Pemaret em Cormaya. A página de Cormaya distingue esse embarque do steamship subterrâneo; não atribuímos os serviços das ilhas ao porto de Edron.</p>`)
 +section('Criaturas por setor',creatures(['Troll','Goblin','Rotworm','Orc','Cyclops','Behemoth','Dragon','Dragon Lord','Hero','Demon'])+'<p>Estas referências abrangem hunts e quests diferentes. O nível sugerido de Trolls ou Cyclops não se aplica a Heroes, Behemoths e Demons; consulte a ficha do objetivo.</p>')
 +section('Checklist antes de sair','<ul class="city-guide-checklist"><li><strong>Destino:</strong> escolha uma hunt, quest ou ilha antes de abrir o mapa.</li><li><strong>Ferramentas:</strong> confira Rope, Shovel e luz; a passagem dos Orcs tem orientação específica para o retorno.</li><li><strong>Suprimentos:</strong> compre cura, comida, mana e munição adequadas ao setor.</li><li><strong>Equipe e acesso:</strong> confira os requisitos das quests avançadas e a Key 6010 quando aplicável.</li><li><strong>Retorno:</strong> preserve o caminho entre entrada e respawn; os marcadores não calculam uma rota desde o depot.</li></ul>')
 +section('Dúvidas rápidas','<details><summary>O atlas da cidade abre a Hero Cave ou Cyclopolis?</summary><p>Ele mostra uma visão geral de Edron. Abra a hunt ou quest escolhida para consultar seu setor e andar específicos.</p></details><details><summary>Cormaya e Eremo ficam dentro da cidade?</summary><p>São destinos relacionados com transporte próprio. Use as fichas das ilhas para conferir o embarque e o serviço desejado.</p></details><details><summary>O conteúdo moderno de Edron está incluído?</summary><p>Este resumo usa as referências clássicas revisadas do catálogo. Novos sistemas, áreas e recompensas posteriores não foram acrescentados como conteúdo do 7.4.</p></details>');
 }else{
 const tombs=[['ancient-ruins','Ancient Ruins','Vashresamun'],['mountain','Mountain','Dipthrah'],['oasis','Oasis','Rahemos'],['peninsula','Peninsula','Omruc'],['shadow','Shadow','Mahrdis'],['stone','Stone','Thalas'],['tarpit','Tarpit','Morguthis'],['library','Library','Ashmunrah']];
 body=section('Prepare sua saída na cidade',`<div class="ab-service-grid">${npc('Ahmet','Ferramentas e suprimentos')}${npc('Memech','Equipamentos e venda de loot')}${npc('Mehkesh','Fluidos de cura e mana')}${npc('Arito','Comida para a expedição')}${npc('Dario','Arcos e munição')}${npc('Captain Sinbeard','Viagem de barco')}</div><p>Abra a ficha para conferir os produtos, preços e o andar registrado. Na referência clássica, várias lojas ficam em pavimentos elevados: o ponto da superfície não substitui a indicação do andar.</p>`)
 +(mythera?section('Mythera · descubra a tumba aberta',`<aside class="city-guide-notice"><strong>Consulte Tothdral antes de partir</strong><ol><li>Abra a ficha de Tothdral e confira a referência de localização.</li><li>Converse com o NPC e pergunte <code>tomb</code>.</li><li>Use o nome informado para escolher a hunt na lista abaixo.</li></ol><p>A documentação oficial descreve sete tumbas em rotação diária, com uma aberta por dia. Quem desloga dentro de uma tumba que fechou retorna à entrada ao entrar novamente. Esta página não calcula a rotação nem apresenta uma tumba como aberta em tempo real.</p><div class="city-guide-links">${link('npc','Tothdral','Localizar Tothdral')}${link('mundo/guia','systems--tomb-rotation-system','Entender a rotação')}</div></aside>`):'')
 +section('Escolha o tipo de exploração',`<div class="ab-access-grid">${box('CAVERNAS','Larvas e Scarabs','São caçadas diferentes: a hunt de Larvas não representa a dificuldade dos Ancient Scarabs. Confira o nível de referência e os perigos da ficha.',hunt('larva-darama')+hunt('scarab-darama')+hunt('ancient-scarab'))}${box('DRAGÕES','Sul, Meio ou Norte','O catálogo separa três áreas de Dragon Lair. Escolha a área primeiro e use seu mapa; o centro da cidade não é uma entrada de Dragon Lair.',hunt('ankrahmun-dragons-south')+hunt('ankrahmun-dragons-middle')+hunt('ankrahmun-dragons-north'))}${box('TUMBAS','Hunt e faraó são objetivos distintos','Uma entrada de tumba não leva diretamente ao boss. Os setores mais profundos podem envolver portais, Scarab Coins, desafios e equipe. Leia a quest antes de planejar os faraós.',link('quest','the-ancient-tombs','The Ancient Tombs · guia'))}</div>`)
 +section('Tumbas: encontre a hunt pelo nome',`<p>Oito referências clássicas do catálogo, incluindo a Library Tomb. Os nomes dos faraós ajudam a reconhecer o destino da quest; não significam que o nível da hunt seja suficiente para enfrentar o boss.${mythera?' A lista clássica de oito locais não é uma previsão das sete tumbas da rotação do servidor.':''}</p><div class="city-guide-table-wrap"><table class="city-guide-table"><caption>Tumbas e faraós associados · base 7.4</caption><thead><tr><th scope="col">Tumba</th><th scope="col">Faraó</th><th scope="col">Guia</th></tr></thead><tbody>${tombs.map(([id,name,boss])=>`<tr><th scope="row">${name} Tomb</th><td>${boss}</td><td>${link('hunt','ankrahmun-'+id+'-tomb','Abrir hunt')}</td></tr>`).join('')}</tbody></table></div>`)
 +section('Quests e referências da região',`<div class="ab-access-grid">${box('THE ANCIENT TOMBS','Helmet of the Ancients','O guia reúne as etapas dos faraós. Planeje equipe, itens e requisitos por tumba; a recompensa não é obtida apenas visitando as entradas.',link('quest','the-ancient-tombs','Consultar guia completo'))}${box('DJINNS','Escolha sua facção com atenção','Os caminhos Efreet e Marid têm guias separados e consequências para os serviços de comércio. Leia os requisitos antes de iniciar uma das opções.',link('quest','the-djinn-war-efreet-faction','Guia Efreet')+link('quest','the-djinn-war-marid-faction','Guia Marid'))}${box('SERPENTINE TOWER','Separe a quest dos mistérios','A ficha White Pearl descreve o conteúdo documentado do catálogo. Não tratamos teorias sobre a torre como solução confirmada de uma quest.',link('quest','serpentine-tower','White Pearl · guia')+link('npc','Tothdral','Ficha de Tothdral'))}</div>`)
 +section('Checklist da expedição','<ul class="city-guide-checklist"><li><strong>Ferramentas:</strong> leve Rope, Shovel e luz conforme a entrada escolhida. Entradas escondidas no deserto podem exigir escavação.</li><li><strong>Suprimentos:</strong> prepare comida, cura, mana, munição e espaço para loot antes de sair.</li><li><strong>Profundidade:</strong> confira o andar da hunt e não atravesse portais sem consultar os requisitos.</li><li><strong>Faraós:</strong> leia os desafios, Scarab Coins e composição de equipe no guia de The Ancient Tombs.</li></ul>')
 +section('Dúvidas rápidas',`<details><summary>O botão do atlas mostra a entrada de uma tumba?</summary><p>Ele abre uma visão geral de Ankrahmun. Cada hunt possui sua própria referência de localização. Escolha a tumba na tabela para consultar o mapa correspondente.</p></details><details><summary>Todas as tumbas têm a mesma dificuldade?</summary><p>Não. Cada ficha possui sua referência de nível e os setores mais profundos podem ser muito mais perigosos. O nível sugerido para caçar não substitui os requisitos dos faraós.</p></details><details><summary>A rotação diária também vale para o clássico?</summary><p>A regra apresentada aqui pertence ao Mythera. Ela aparece somente quando esse servidor está selecionado; não é uma regra geral da base 7.4.</p></details>`);
 }
 const sources=name==='Isle of the Kings'?[['/quests/the-white-raven-monastery/','White Raven Monastery · acesso e investigação'],['/chaves/key-3350/','Key 3350 · área restrita'],['/hunts/carlin-isle-kings-skeletons/','Skeletons · acesso e catacumbas'],['https://www.tibiawiki.com.br/wiki/Captain_Jack','Captain Jack · retorno e restrição de passagem']]:name==='Jakundaf Desert'?[['/quests/the-desert-dungeon/','The Desert Dungeon · roteiro clássico de quatro vocações'],['/chaves/key-4022/','Key 4022 · início da sequência da biblioteca'],['/chaves/key-4055/','Key 4055 · Panpipe']]:name==='Kazordoon'?[['/quests/emperor-s-cookies/','Emperor’s Cookies · roteiro e chaves'],['/chaves/key-3802/','Key 3802 · Dwacatra'],['https://www.tibiawiki.com.br/wiki/Brodrosch','Brodrosch · comparação histórica do steamship']]:name==='Greenshore'?[['/npcs/tokel/','Tokel · alimentos da base clássica'],['/npcs/ulrik/','Ulrik · equipamentos da base clássica'],['https://www.tibiawiki.com.br/wiki/Greenshore','Greenshore · comparação geográfica atual']]:name==='Hellgate'?[['/chaves/key-3012/','Key 3012 · acesso ilustrado e compra'],['/quests/draconia/','Draconia · conexão e roteiro clássico'],['https://www.tibiawiki.com.br/wiki/Hellgate','Hellgate · comparação geográfica atual']]:name==='Ice Islands'?[['/quests/alawar-s-vault/','Alawar’s Vault · acessos e fontes clássicas'],['/chaves/key-4503/','Key 4503 · sequência de Folda'],['https://www.tibiawiki.com.br/wiki/Ice_Islands','Ice Islands · referência atual, com regiões posteriores']]:name==='Ghostlands'?[['/quests/the-queen-of-the-banshees/','The Queen of the Banshees · roteiro clássico'],['/quests/the-white-raven-monastery/','The White Raven Monastery · acesso da ilha'],['https://www.tibiawiki.com.br/wiki/Ghostlands','Ghostlands · comparação geográfica']]:name==='Green Claw Swamp'?[['/chaves/key-5000/','Key 5000 · Wyda'],['/chaves/key-5010/','Key 5010 · villa'],['/quests/blood-herb/','Blood Herb · guia clássico'],['/quests/voodoo-doll/','Voodoo Doll · guia clássico']]:name==='Ghostland'?[['https://mythera74.gitbook.io/mythera74/events-new/halloween-2026/halloween-npc-store','Farmer · documentação oficial do evento']]:name==='Fields of Glory'?[['https://www.tibiawiki.com.br/wiki/Fields_of_Glory','Fields of Glory · comparação geográfica'],['/npcs/humphrey/','Humphrey · referência clássica do catálogo']]:name==='Folda'?[['/quests/alawar-s-vault/','Alawar’s Vault · roteiro e fontes'],['/chaves/key-4503/','Key 4503 · acesso de Folda'],['https://www.tibiawiki.com.br/wiki/Svenson','Svenson · transporte']]:name==='Frostveil'?[['https://otlab.net/mythera/loot-prices','OTLab · Eirik e preços comunitários'],['https://mythera74.gitbook.io/mythera74/events-new/halloween-2026/gravepaw-raids','Mythera · documentação de Gravepaw']]:name==='Elvenbane'?[['https://www.tibiawiki.com.br/wiki/Elvenbane','Elvenbane · geografia e acesso'],['/hunts/abdendriel-elvenbane-dragon/','Dragon · referência clássica da torre']]:name==="Eremo's Island"?[['https://www.tibiawiki.com.br/wiki/Eremo','Eremo · localização e retorno'],['https://www.tibiawiki.com.br/wiki/Pemaret','Pemaret · embarque em Cormaya']]:name==='Fibula'?[['/quests/fibula/','Deeper Fibula · guia clássico e fontes'],['/chaves/key-3940/','Key 3940 · compra e diálogo'],['/chaves/key-3980/','Key 3980 · coleta e uso']]:name==='Draconia'?[['https://www.tibiawiki.com.br/wiki/Draconia_Quest','Draconia · acesso e mecanismos'],['/chaves/key-3012/','Key 3012 · entrada de Hellgate'],['/chaves/key-3001/','Key 3001 · início da sequência']]:name==='Drefia'?[['https://www.tibiawiki.com.br/wiki/Drefia','Drefia · referência geográfica atual'],['/quests/medusa-shield/','Medusa Shield · requisitos e roteiro']]:name==='Edron'?[['https://www.tibiawiki.com.br/wiki/Edron','Edron · referência geográfica atual'],['/chaves/key-6010/','Key 6010 · fontes e acesso']]:name==='Cormaya'?[['https://www.tibiawiki.com.br/wiki/Cormaya','Cormaya · referência geográfica atual'],['https://www.tibiawiki.com.br/wiki/Gurbasch','Gurbasch · presença anterior ao 7.4 e transporte']]:name==='Darashia'?[['https://www.tibiawiki.com.br/wiki/Darashia','Darashia · referência geográfica atual'],['https://www.tibiawiki.com.br/wiki/Asima','Asima · introduzida no 7.6'],['https://www.tibiawiki.com.br/wiki/Medusa_Shield_Quest','Medusa Shield · requisitos e acesso']]:name==="Ashta'daramai"?[['https://www.tibiawiki.com.br/wiki/Ashta%27daramai','Ashta’daramai · referência da fortaleza'],['https://www.tibiawiki.com.br/wiki/The_Djinn_War_Quest','The Djinn War · requisitos e facções']]:name==='Carlin'?[['https://www.tibiawiki.com.br/wiki/Carlin','Carlin · referência geográfica atual'],['/chaves/key-3520/','Key 3520 · obtenção e acesso'],['/chaves/key-3350/','Key 3350 · referência do mosteiro']]:name==='Arredores de Venore'?[['https://www.tibiawiki.com.br/wiki/Green_Claw_Swamp','Green Claw Swamp · referência geográfica atual'],['/chaves/key-5010/','Key 5010 · fontes e caminho ilustrado']]:name==='Arredores de Kazordoon'?[['https://www.tibiawiki.com.br/wiki/Dwarf_Bridge','Dwarf Bridge · localização e travessia'],['/chaves/key-3899/','Key 3899 · acesso da Paradox Tower']]:name==='Ancient Temple'?[['https://www.tibiawiki.com.br/wiki/Ancient_Temple','Ancient Temple · referência geográfica atual'],['/chaves/key-3600/','Key 3600 · fontes e caminho ilustrado'],['/chaves/key-3620/','Key 3620 · acesso de Mintwallin']]:[['https://www.tibiawiki.com.br/wiki/Ankrahmun','Ankrahmun · referência geográfica atual'],['https://www.tibiawiki.com.br/wiki/Helmet_of_the_Ancients_Quest','The Ancient Tombs · introduzida no 7.4'],...(mythera?[['https://mythera74.gitbook.io/mythera74/systems/tomb-rotation-system','Mythera · documentação oficial da rotação']]:[])];
 return `<section class="ab-city-guide city-detailed-guide ${name==='Ankrahmun'?'city-guide-desert':''}" aria-label="Guia de ${esc(name)}"><div class="ab-city-intro"><p class="eyebrow">${name==='Isle of the Kings'?'ILHA · SUL DE GHOSTLANDS':name==='Jakundaf Desert'?'DESERTO · CONTINENTE PRINCIPAL':name==='Kazordoon'?'CIDADE DOS ANÕES · MONTANHA':name==='Greenshore'?'COMUNIDADE · NORTE DE THAIS':name==='Hellgate'?'SUBSOLO · AB’DENDRIEL':name==='Ice Islands'?'ARQUIPÉLAGO CLÁSSICO · CARLIN':name==='Ghostlands'?'REGIÃO · OESTE DE CARLIN':name==='Ghostland'?'MYTHERA · HALLOWEEN 2026':name==='Green Claw Swamp'?'PÂNTANO · REGIÃO DE VENORE':name==='Fields of Glory'?'REGIÃO · NORTE DE CARLIN':name==='Folda'?'ICE ISLANDS · FOLDA':name==='Frostveil'?'MYTHERA · LOCAL PRÓPRIO':name==='Elvenbane'?'CASTELO · AB’DENDRIEL':name==="Eremo's Island"?'ILHA · REGIÃO DE EDRON':name==='Fibula'?'ILHA · SUDOESTE DE THAIS':name==='Draconia'?'REGIÃO · AB’DENDRIEL':name==='Drefia'?'REGIÃO · OESTE DE DARASHIA':name==='Edron'?'CIDADE · EDRON':name==='Cormaya'?'ILHA · REGIÃO DE EDRON':name==='Darashia'?'CIDADE · NORTE DE DARAMA':name==='Carlin'?'CIDADE · NOROESTE DO CONTINENTE':name==="Ashta'daramai"?'REGIÃO · KHA’ZEEL':name==='Ankrahmun'?'CIDADE · SUL DE DARAMA':name==='Ancient Temple'?'REGIÃO · NORTE DE THAIS':name==='Arredores de Venore'?'REGIÃO · VENORE':'REGIÃO · KAZORDOON'}</p><h4>${name==='Isle of the Kings'?'Da passagem com Dalbrect às catacumbas':name==='Jakundaf Desert'?'Prepare o grupo, as chaves e o percurso':name==='Kazordoon'?'Serviços por andar e expedições pela montanha':name==='Greenshore'?'Comércio local e preparação da próxima viagem':name==='Hellgate'?'Prepare a chave, a travessia e a saída':name==='Ice Islands'?'Escolha a ilha antes de embarcar':name==='Ghostlands'?'Das primeiras cavernas aos sete selos':name==='Ghostland'?'Farmer, trocas e preparação para o evento':name==='Green Claw Swamp'?'Wyda, quests do pântano e Black Knight Villa':name==='Fields of Glory'?'Explore as planícies com um destino definido':name==='Folda'?'Da balsa às cavernas e chaves das ilhas':name==='Frostveil'?'Comércio com Eirik e referências do cemitério':name==='Elvenbane'?'Do calabouço aos andares da torre':name==="Eremo's Island"?'Visite o sábio e organize seu retorno':name==='Fibula'?'Prepare as chaves e escolha a profundidade':name==='Draconia'?'Prepare a travessia, as chaves e a volta':name==='Drefia'?'Escolha seu setor nas ruínas clássicas':name==='Edron'?'Da cidade às grandes expedições':name==='Cormaya'?'Sua conexão entre Edron, Eremo e Kazordoon':name==='Darashia'?'Da cidade ao deserto: prepare cada destino':name==='Carlin'?'Prepare a cidade. Escolha sua próxima aventura.':name==="Ashta'daramai"?'Acesso Marid e comércio dos Blue Djinns':name==='Ankrahmun'?'Sua base para explorar o deserto e as tumbas':name==='Ancient Temple'?'Um complexo de caminhos, não uma única hunt':name==='Arredores de Venore'?'Escolha seu caminho entre o pântano e os acampamentos':'Das colinas às minas: prepare cada destino'}</h4><p>${esc(descriptions[name])}</p></div>${scope}${body}<details class="ab-city-sources"><summary>Fontes, versão e limites das referências</summary><p>${name==='Ghostland'?'Revisão de 23/10/2026. Referência sazonal da documentação oficial do Mythera. A ficha não confirma disponibilidade em tempo real nem coordenadas do acesso.':name==='Frostveil'?'Revisão de 23/10/2026. As ofertas de Eirik são comunitárias, não cotações ao vivo. A referência de Frostveil Cemetery vem da documentação do evento Gravepaw. A página preserva os limites de localização e acesso das fontes disponíveis.':'Revisão de 23/10/2026. O resumo utiliza o catálogo 7.4 e guias já publicados. As wikis atuais servem para comparação geográfica; mudanças posteriores não foram incorporadas como conteúdo clássico. Mapas comunitários são referências de posição, não rotas validadas em campo.'}</p><ul>${sources.map(([url,title])=>`<li><a href="${url}" target="_blank" rel="noopener">${title} ↗</a></li>`).join('')}</ul></details></section>`;
}
window.CityGuides={render,descriptions};
})();
